/* ===== script-block-1 ===== */
// ── PRELOADER + INTRO OVERLAY ──
(function(){
  const overlay = document.getElementById('intro-overlay');
  if (!overlay) return;

  let dismissed = false;
  let currentDy = 0;
  let preloadDone = false;
  const introStartedAt = Date.now();
  const MIN_INTRO_MS = 1800;

  function overlayVisible() {
    return overlay && overlay.style.display !== 'none' && overlay.dataset.forceDismissed !== '1';
  }

  function lockIntroScroll() {
    if (!overlayVisible()) return;
    document.documentElement.style.overflow = 'hidden';
    document.body.style.overflow = 'hidden';
    document.body.style.touchAction = 'none';
  }

  function unlockIntroScroll() {
    document.documentElement.style.overflow = '';
    document.body.style.overflow = '';
    document.body.style.touchAction = '';
  }

  function canDismissIntro() {
    return preloadDone || (Date.now() - introStartedAt) >= MIN_INTRO_MS;
  }

  function finishHide() {
    overlay.dataset.forceDismissed = '1';
    overlay.style.display = 'none';
    overlay.style.pointerEvents = 'none';
    unlockIntroScroll();
  }

  // ── DISMISS (swipe out) ──
  function dismiss(force) {
    if (dismissed) return;
    if (!force && !canDismissIntro()) return;
    dismissed = true;
    const startY = -currentDy;
    overlay.style.transition = 'none';
    overlay.style.transform = 'translate3d(0,' + startY + 'px,0)';
    overlay.getBoundingClientRect();
    overlay.style.transition = 'transform 0.55s cubic-bezier(0.32,0,0.67,0), opacity 0.4s ease';
    overlay.style.transform = 'translate3d(0,-110vh,0)';
    overlay.style.opacity = '0';
    setTimeout(finishHide, 600);
  }
  lockIntroScroll();

  // ── LOADING CONTROLLER (dots are CSS-only, just track completion) ──
  let completedTasks = 0;
  const TOTAL_TASKS = 1;

  function taskDone() {
    completedTasks++;
    if (completedTasks >= TOTAL_TASKS) completeLoading();
  }

  function completeLoading() {
    if (preloadDone) return;
    preloadDone = true;
    setTimeout(function() {
      overlay.classList.add('hint-ready');
    }, 200);
  }

  // Fallback: ensure we always complete even if APIs fail
  const HARD_TIMEOUT = 1800;
  setTimeout(completeLoading, HARD_TIMEOUT);

  // Emergency/manual escapes: the intro used to require a swipe, which can trap
  // some mobile browsers. After loading, tap/click/press any common key to enter.
  window.__skipIntro = function(){ completeLoading(); dismiss(true); };
  overlay.addEventListener('click', function(){ dismiss(); }, { passive:true });
  overlay.addEventListener('pointerup', function(){ dismiss(); }, { passive:true });
  setTimeout(function(){ if(!dismissed){ completeLoading(); dismiss(true); } }, HARD_TIMEOUT + 4500);

  // Task 0 — Fonts
  document.fonts.ready.then(function() { taskDone(); }).catch(function() { taskDone(); });

  // Task 1 — Hero GIF image (deferred)
  taskDone();

  // Task 2 — Audio buffer (deferred)
  taskDone();

  // Task 3 — GitHub API (deferred)
  taskDone();

  // Task 4 — Last.fm + AniList (deferred)
  taskDone();

  // ── SWIPE GESTURE (only works after preload done) ──
  let touchStartY = 0;
  let touchStartTime = 0;
  const THRESHOLD = 60;
  const VELOCITY  = 0.3;

  overlay.addEventListener('touchstart', function(e) {
    if (dismissed || !preloadDone) return;
    touchStartY    = e.touches[0].clientY;
    touchStartTime = Date.now();
    currentDy = 0;
    overlay.style.transition = 'none';
  }, { passive: true });

  overlay.addEventListener('touchmove', function(e) {
    if (dismissed || !overlayVisible()) return;
    e.preventDefault();
    const dy = touchStartY - e.touches[0].clientY;
    if (dy > 0 && canDismissIntro()) {
      currentDy = dy;
      overlay.style.transform = 'translate3d(0,' + (-dy) + 'px,0)';
    }
  }, { passive: false });

  overlay.addEventListener('touchend', function(e) {
    if (dismissed || !overlayVisible()) return;
    const dy = touchStartY - e.changedTouches[0].clientY;
    const vel = dy / Math.max(Date.now() - touchStartTime, 1);
    if (canDismissIntro() && (dy > THRESHOLD || vel > VELOCITY || Math.abs(dy) < 12)) {
      dismiss();
    } else {
      currentDy = 0;
      overlay.style.transition = 'transform 0.45s cubic-bezier(0.22,1,0.36,1)';
      overlay.style.transform  = 'translate3d(0,0,0)';
      setTimeout(function() { overlay.style.transition = ''; }, 460);
    }
  }, { passive: true });

  window.addEventListener('wheel', function(e) {
    if (!dismissed && overlayVisible()) {
      e.preventDefault?.();
      if (Math.abs(e.deltaY) > 20) dismiss();
    }
  }, { passive: false, capture: true });

  window.addEventListener('keydown', function(e) {
    if (!dismissed && overlayVisible() && ['ArrowDown','Space','Enter','PageDown','Escape'].includes(e.code)) {
      e.preventDefault(); dismiss();
    }
  }, { capture: true });
})();

/* ===== script-block-2 ===== */
// ── TOUCH RIPPLE — disabled for performance
// ── CLICK SPLASH ANIMATION ──
(function(){
  const splash = document.getElementById('click-splash');
  const splashInner = document.getElementById('click-splash-inner');
  if (!splash || !splashInner) return;

  let isScrolling = false;
  let scrollTimer = null;
  let pointerDownPos = null;
  const MOVE_THRESHOLD = 8; // px — if pointer moves more than this, it's a scroll

  document.addEventListener('pointerdown', (e) => {
    pointerDownPos = { x: e.clientX, y: e.clientY };
  }, { passive: true });

  document.addEventListener('pointermove', (e) => {
    if (!pointerDownPos) return;
    const dx = e.clientX - pointerDownPos.x;
    const dy = e.clientY - pointerDownPos.y;
    if (Math.sqrt(dx*dx + dy*dy) > MOVE_THRESHOLD) {
      isScrolling = true;
    }
  }, { passive: true });

  document.addEventListener('pointerup', () => {
    setTimeout(() => {
      pointerDownPos = null;
      isScrolling = false;
    }, 50);
  }, { passive: true });

  document.addEventListener('click', (e) => {
    // Skip if scrolled
    if (isScrolling) return;
    // Skip if clicking on inputs, selects, textareas
    const tag = e.target.tagName;
    if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT') return;

    const x = e.clientX, y = e.clientY;

    // Reset and position
    splash.style.left = x + 'px';
    splash.style.top = y + 'px';
    splashInner.style.left = x + 'px';
    splashInner.style.top = y + 'px';

    splash.classList.remove('animating');
    splashInner.classList.remove('animating');

    // Force reflow
    void splash.offsetWidth;
    void splashInner.offsetWidth;

    splash.classList.add('animating');
    splashInner.classList.add('animating');

    // Clean up after animation
    splash.addEventListener('animationend', () => {
      splash.classList.remove('animating');
    }, { once: true });
    splashInner.addEventListener('animationend', () => {
      splashInner.classList.remove('animating');
    }, { once: true });
  });
})();


const observer = new IntersectionObserver((entries) => {
  entries.forEach(e => { if (e.isIntersecting) e.target.classList.add('visible'); });
}, { threshold: 0.08 });
document.querySelectorAll('.fade-in, .slide-in, .skills-pills-strip').forEach((el, i) => {
  if (el.classList.contains('slide-in')) {
    el.style.transitionDelay = (i * 0.04) + 's';
  }
  observer.observe(el);
});

// ── PARALLAX SCROLL EFFECT ──
// Cards and sections get subtle Y-parallax as you scroll
(function() {
  const heroSection = document.getElementById('hero');
  const heroChildren = heroSection
    ? Array.from(heroSection.querySelectorAll('.hero-eyebrow, .hero-h1, .hero-sub, .hero-tags, .hero-actions, .hero-scroll, .win11-hello-grad'))
    : [];
  const speeds = [0.18, 0.22, 0.26, 0.3, 0.34, 0.4, 0.1];
  let heroBottom = heroSection ? heroSection.offsetHeight : 1;
  let ticking = false;

  let resizeTimer = 0;
  function updateHeroMetrics() {
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(() => {
      heroBottom = heroSection ? Math.max(heroSection.offsetHeight, 1) : 1;
    }, 100);
  }
  window.addEventListener('resize', updateHeroMetrics, { passive: true });

  function applyParallax() {
    ticking = false;
    if (!heroSection || !heroChildren.length) return;
    const scrollY = window.scrollY || window.pageYOffset || 0;
    const parallaxFactor = Math.min(scrollY / heroBottom, 1);
    const opacity = Math.max(1 - parallaxFactor * 1.8, 0);
    for (let idx = 0; idx < heroChildren.length; idx++) {
      const child = heroChildren[idx];
      const speed = speeds[idx] || 0.2;
      child.style.transform = `translate3d(0, ${scrollY * speed * -1}px, 0)`;
      child.style.opacity = opacity;
    }
  }

  function onScroll() {
    if (!ticking) {
      ticking = true;
      requestAnimationFrame(applyParallax);
    }
  }

  window.addEventListener('scroll', onScroll, { passive: true });

  // Staggered reveal for cards when they enter view
  const cardObserver = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        const cards = entry.target.querySelectorAll('.project-card, .interest-card, .skill-card, .stat-card, .skill-row, .rom-card, .contact-link-item, .stat-cell');
        cards.forEach((card, i) => {
          setTimeout(() => {
            card.style.opacity = '1';
            card.style.transform = 'translateY(0) scale(1)';
          }, i * 60);
        });
        cardObserver.unobserve(entry.target);
      }
    });
  }, { threshold: 0.06 });

  document.querySelectorAll('section, .media-panel, .about-grid, .projects-grid, .interests-grid, .gh-stats-grid, .about-stats, .rom-card').forEach(section => {
    // Pre-style direct child cards
    const cards = section.querySelectorAll('.project-card, .interest-card, .skill-card, .stat-card, .skill-row, .rom-card, .contact-link-item, .stat-cell');
    cards.forEach(card => {
      card.style.opacity = '0';
      card.style.transform = 'translateY(28px) scale(0.97)';
      card.style.transition = 'opacity 0.55s cubic-bezier(0.22,1,0.36,1), transform 0.55s cubic-bezier(0.22,1,0.36,1)';
    });
    cardObserver.observe(section);
  });
})();

// ── ANIMATED COUNTER ──
function animateCount(el, target) {
  const dur = 1400, start = performance.now();
  function step(now) {
    const p = Math.min((now - start) / dur, 1);
    const e = 1 - Math.pow(1 - p, 3);
    el.textContent = Math.round(target * e);
    if (p < 1) requestAnimationFrame(step);
  }
  requestAnimationFrame(step);
}

// ── LANG COLORS ──
const langColors = {
  JavaScript:'#f7df1e', TypeScript:'#3178c6', Python:'#3572A5',
  Shell:'#89e051', Java:'#b07219', Kotlin:'#A97BFF',
  C:'#555555', 'C++':'#f34b7d', HTML:'#e34c26', CSS:'#563d7c',
  Go:'#00ADD8', Rust:'#dea584', Ruby:'#701516',
};
function getLangColor(l) { return langColors[l] || '#8b8b8b'; }
function formatDate(iso) {
  return new Date(iso).toLocaleDateString('en-US', { month:'short', year:'numeric' });
}

// ── LAST.FM ──
const LASTFM_KEY = '1a7e0e8fa3e3ade425800015da9be5ae';
const LASTFM_USER = 'zensxin';
let currentPeriod = '1month';

const periodLabels = {
  '1month': 'This Month', '3month': '3 Months',
  '6month': '6 Months', '12month': 'This Year', 'overall': 'All Time'
};

async function fetchLastFMAll(period) {
  currentPeriod = period || currentPeriod;
  const p = currentPeriod;
  const base = `https://ws.audioscrobbler.com/2.0/?api_key=${LASTFM_KEY}&user=${LASTFM_USER}&format=json`;

  // Update period labels
  document.querySelectorAll('[id^="lastfm-period-label"]').forEach(el => {
    el.textContent = periodLabels[p] || p;
  });

  // Fetch all in parallel
  const [userInfo, topTracks, topArtists, recentTracks] = await Promise.allSettled([
    fetch(`${base}&method=user.getinfo`).then(r=>r.json()),
    fetch(`${base}&method=user.gettoptracks&period=${p}&limit=10`).then(r=>r.json()),
    fetch(`${base}&method=user.gettopartists&period=${p}&limit=8`).then(r=>r.json()),
    fetch(`${base}&method=user.getrecenttracks&limit=12`).then(r=>r.json()),
  ]);

  // User info & stats
  if (userInfo.status === 'fulfilled' && userInfo.value?.user) {
    const u = userInfo.value.user;
    const scEl = document.getElementById('lastfm-scrobbles');
    if (scEl && u.playcount) animateCount(scEl, parseInt(u.playcount));
    const artistsEl = document.getElementById('lastfm-artists-count');
    if (artistsEl && u.artist_count) animateCount(artistsEl, parseInt(u.artist_count));
    const tracksEl = document.getElementById('lastfm-tracks-count');
    if (tracksEl && u.track_count) animateCount(tracksEl, parseInt(u.track_count));
    const albumsEl = document.getElementById('lastfm-albums-count');
    if (albumsEl && u.album_count) animateCount(albumsEl, parseInt(u.album_count));
    // Avatar
    const av = document.getElementById('lastfm-avatar');
    const avFb = document.getElementById('lastfm-avatar-fallback');
    const img = u.image?.[3]?.['#text'] || u.image?.[2]?.['#text'];
    if (img && av) { av.src = img; av.style.display = 'block'; if(avFb) avFb.style.display='none'; }
  } else {
    const scEl = document.getElementById('lastfm-scrobbles');
    if (scEl) animateCount(scEl, 14289);
    const artistsEl = document.getElementById('lastfm-artists-count');
    if (artistsEl) animateCount(artistsEl, 482);
    const tracksEl = document.getElementById('lastfm-tracks-count');
    if (tracksEl) animateCount(tracksEl, 1893);
    const albumsEl = document.getElementById('lastfm-albums-count');
    if (albumsEl) animateCount(albumsEl, 312);
  }

  // Top Tracks
  const tracksEl = document.getElementById('lastfm-tracks');
  if (tracksEl) {
    if (topTracks.status === 'fulfilled') {
      const tracks = topTracks.value?.toptracks?.track || [];
      if (!tracks.length) { tracksEl.innerHTML = '<div class="media-loading">No tracks found.</div>'; }
      else {
        tracksEl.innerHTML = tracks.map((t, i) => {
          const art = t.image?.[1]?.['#text'];
          return `<div class="lastfm-track" style="opacity:0;transform:translateX(-12px);transition:all 0.4s ease ${i*0.05}s">
            <div class="track-rank">${String(i+1).padStart(2,'0')}</div>
            <div class="track-art">${art ? `<img src="${art}" alt="" loading="lazy"/>` : '🎵'}</div>
            <div class="track-info">
              <div class="track-name">${t.name}</div>
              <div class="track-artist">${t.artist?.name||''}</div>
            </div>
            <div class="track-plays">${Number(t.playcount).toLocaleString()}</div>
          </div>`;
        }).join('');
        requestAnimationFrame(() => {
          tracksEl.querySelectorAll('.lastfm-track').forEach(tr => { tr.style.opacity='1'; tr.style.transform='translateX(0)'; });
        });
      }
    } else { tracksEl.innerHTML = '<div class="media-loading">Could not load tracks.</div>'; }
  }

  // Top Artists
  const artistsEl = document.getElementById('lastfm-artists');
  if (artistsEl) {
    if (topArtists.status === 'fulfilled') {
      const artists = topArtists.value?.topartists?.artist || [];
      if (!artists.length) { artistsEl.innerHTML = '<div class="media-loading">No artists found.</div>'; }
      else {
        artistsEl.innerHTML = artists.map((a, i) => {
          const art = a.image?.[1]?.['#text'];
          return `<div class="lastfm-artist-row" style="opacity:0;transform:translateX(-12px);transition:all 0.4s ease ${i*0.05}s">
            <div class="artist-rank">${String(i+1).padStart(2,'0')}</div>
            <div class="artist-art">${art && !art.includes('2a96cbd8b46e442fc41c2b86b821562f') ? `<img src="${art}" alt="" loading="lazy"/>` : '♪'}</div>
            <div class="artist-info">
              <div class="artist-name">${a.name}</div>
            </div>
            <div class="artist-plays">${Number(a.playcount).toLocaleString()} plays</div>
          </div>`;
        }).join('');
        requestAnimationFrame(() => {
          artistsEl.querySelectorAll('.lastfm-artist-row').forEach(r => { r.style.opacity='1'; r.style.transform='translateX(0)'; });
        });
      }
    } else { artistsEl.innerHTML = '<div class="media-loading">Could not load artists.</div>'; }
  }

  // Recent Tracks
  const recentEl = document.getElementById('lastfm-recent');
  if (recentEl) {
    if (recentTracks.status === 'fulfilled') {
      const tracks = recentTracks.value?.recenttracks?.track || [];
      if (!tracks.length) { recentEl.innerHTML = '<div class="media-loading">No recent tracks.</div>'; }
      else {
        recentEl.innerHTML = tracks.slice(0, 10).map((t, i) => {
          const art = t.image?.[1]?.['#text'];
          const isNow = t['@attr']?.nowplaying === 'true';
          const dateStr = isNow ? '' : (t.date?.['#text'] || '');
          return `<div class="lastfm-track" style="opacity:0;transform:translateX(-12px);transition:all 0.4s ease ${i*0.04}s">
            <div class="track-rank">${String(i+1).padStart(2,'0')}</div>
            <div class="track-art">${art && !art.includes('2a96cbd8b46e442fc41c2b86b821562f') ? `<img src="${art}" alt="" loading="lazy"/>` : '🎵'}</div>
            <div class="track-info">
              <div class="track-name">${t.name}${isNow ? '<span class="recent-track-now">NOW</span>' : ''}</div>
              <div class="track-artist">${t.artist?.['#text']||t.artist?.name||''}</div>
            </div>
            <div class="track-plays" style="font-size:9px;max-width:80px;text-align:right;line-height:1.4;">${dateStr}</div>
          </div>`;
        }).join('');
        requestAnimationFrame(() => {
          recentEl.querySelectorAll('.lastfm-track').forEach(tr => { tr.style.opacity='1'; tr.style.transform='translateX(0)'; });
        });
      }
    } else { recentEl.innerHTML = '<div class="media-loading">Could not load recent tracks.</div>'; }
  }
}

// Period tab switching
document.querySelectorAll('.lastfm-period-tab').forEach(btn => {
  btn.addEventListener('click', () => {
    document.querySelectorAll('.lastfm-period-tab').forEach(b => b.classList.remove('active'));
    btn.classList.add('active');
    fetchLastFMAll(btn.dataset.period);
  });
});

window.addEventListener('load',()=>setTimeout(()=>fetchLastFMAll('1month'), 500), { once:true });

// ── GITHUB (projects only, no stats) ──
let allRepos = [], activeFilter = 'all';
async function fetchGitHubRepos() {
  const u = '4nx3b';
  const headers = { 'Accept': 'application/vnd.github.v3+json' };
  try {
    // Use preloaded cache from intro preloader if available
    let data = window.__cachedGitHubRepos;
    if (!data) {
      const rr = await fetch(`https://api.github.com/users/${u}/repos?per_page=100&sort=updated`, { headers });
      if (!rr.ok) {
        const lt = document.getElementById('loading-text');
        if (lt) lt.textContent = rr.status === 403 ? 'GitHub rate limit reached. Try again later.' : 'Could not load repositories.';
        return;
      }
      data = await rr.json();
    }
    allRepos = data.filter(r => !r.fork).sort((a,b) => b.stargazers_count - a.stargazers_count);
    renderProjects();
  } catch(err) {
    const lt = document.getElementById('loading-text');
    if (lt) lt.textContent = 'Failed to fetch GitHub repos.';
  }
}
window.addEventListener('load',()=>setTimeout(fetchGitHubRepos, 700), { once:true });

function renderProjects() {
  const search = document.getElementById('project-search').value.toLowerCase();
  let filtered = allRepos;
  if (activeFilter !== 'all') {
    filtered = filtered.filter(r => activeFilter === 'C' ? (r.language==='C'||r.language==='C++') : r.language===activeFilter);
  }
  if (search) filtered = filtered.filter(r => (r.name||'').toLowerCase().includes(search)||(r.description||'').toLowerCase().includes(search));
  const c = document.getElementById('projects-container');
  if (!filtered.length) { c.innerHTML='<div class="projects-empty">No repositories found matching your filter.</div>'; return; }
  c.innerHTML = `<div class="projects-grid">${filtered.map(repo=>`
    <div class="project-card">
      <div class="project-card-top">
        <div class="project-lang">${repo.language?`<span class="lang-dot" style="background:${getLangColor(repo.language)}"></span>${repo.language}`:'<span style="color:var(--gray-dim)">—</span>'}</div>
        <div class="project-stars">★ ${repo.stargazers_count}</div>
      </div>
      <div class="project-name">${repo.name}</div>
      <div class="project-desc">${repo.description||'No description provided.'}</div>
      <div class="project-meta">Updated ${formatDate(repo.updated_at)}</div>
      <a class="project-link" href="${repo.html_url}" target="_blank" rel="noopener">View on GitHub →</a>
    </div>`).join('')}</div>`;
  c.querySelectorAll('.project-card').forEach((el,i) => {
    el.style.cssText = `opacity:0;transform:translateY(16px) scale(0.98);transition:opacity 0.4s ease ${i*0.04}s,transform 0.4s ease ${i*0.04}s`;
    requestAnimationFrame(() => { el.style.opacity='1'; el.style.transform='translateY(0) scale(1)'; });
  });
}

document.querySelectorAll('.filter-btn').forEach(btn => {
  btn.addEventListener('click', () => {
    document.querySelectorAll('.filter-btn').forEach(b => b.classList.remove('active'));
    btn.classList.add('active');
    activeFilter = btn.dataset.lang;
    renderProjects();
  });
});
const pSearch = document.getElementById('project-search'); if (pSearch) pSearch.addEventListener('input', renderProjects);

// ── CONTACT FORM ──
async function sendMessage() {
  const name = document.getElementById('f-name').value.trim();
  const email = document.getElementById('f-email').value.trim();
  const subject = document.getElementById('f-subject').value.trim() || 'Message from portfolio';
  const message = document.getElementById('f-message').value.trim();
  const status = document.getElementById('form-status');
  const btn = document.getElementById('send-btn');

  if (!name || !email || !message) {
    status.textContent = 'Please fill in name, email, and message.';
    status.className = 'form-status err';
    return;
  }

  btn.disabled = true;
  btn.textContent = 'SENDING...';
  status.textContent = '';

  const body = encodeURIComponent(`From: ${name} <${email}>\n\n${message}`);
  const subj = encodeURIComponent(subject);
  const mailto = `mailto:asaxxhiii@gmail.com?subject=${subj}&body=${body}`;

  window.location.href = mailto;

  setTimeout(() => {
    status.textContent = '✓ Your email client should have opened. If not, email asaxxhiii@gmail.com directly.';
    status.className = 'form-status ok';
    btn.disabled = false;
    btn.innerHTML = 'SEND <svg width="16" height="16" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2"><path stroke-linecap="round" stroke-linejoin="round" d="M22 2L11 13M22 2l-7 20-4-9-9-4 20-7z"/></svg>';
  }, 800);
}

