/* ===== script-block-4 ===== */
(function(){
let animeCache = [];
let currentFilter = 'ALL';
let currentPage = 1;
const PER_PAGE = 15; // max items per page

async function rebuildAni(){
  const list = document.getElementById('anilist-list');
  if (!list) return;

  const query = `
  query{
   User(name:"zensxin"){
     avatar{large}
     statistics{anime{count episodesWatched minutesWatched}}
   }
   MediaListCollection(userName:"zensxin",type:ANIME){
    lists{
     status
     entries{
      status progress score
      media{
        id
        episodes
        title{romaji}
        coverImage{large}
      }
     }
    }
   }
  }`;

  try {
   const r = await fetch('https://graphql.anilist.co', {
    method: 'POST',
    headers: {'Content-Type':'application/json'},
    body: JSON.stringify({query})
   });
   const d = await r.json();

   if (d.data?.User?.avatar?.large) {
     const a = document.getElementById('anilist-avatar');
     if (a) a.src = d.data.User.avatar.large;
   }

   animeCache = [];
   d.data.MediaListCollection.lists.forEach(group => {
     group.entries.forEach(entry => animeCache.push({...entry, status: group.status}));
   });

   const st = d.data.User.statistics.anime;
   const mins = document.getElementById('anilist-mins');
   if (mins) {
     mins.innerHTML = `${st.count.toLocaleString()} anime &nbsp;•&nbsp; ${st.episodesWatched.toLocaleString()} episodes &nbsp;•&nbsp; ${(Math.round(st.minutesWatched/60)).toLocaleString()} hrs watched`;
   }

   function animateAniPageSwap(nextPage){
     const box = document.querySelector('.anilist-scroll-box');
     if (!box || Number(nextPage || 1) === Number(currentPage || 1)) {
       window.renderAniFilter(currentFilter, nextPage);
       return;
     }
     box.classList.remove('pager-swap-in','pager-swap-out');
     box.classList.add('pager-swap-out');
     setTimeout(() => {
       window.renderAniFilter(currentFilter, nextPage);
       requestAnimationFrame(() => {
         box.classList.remove('pager-swap-out');
         box.classList.add('pager-swap-in');
         setTimeout(() => box.classList.remove('pager-swap-in'), 280);
       });
     }, 115);
   }
   window.animateAniPageSwap = animateAniPageSwap;

   window.renderAniFilter = function(filter, page){
     currentFilter = filter || currentFilter;
     currentPage = page || 1;
     let items = animeCache;
     if (currentFilter !== "ALL") items = items.filter(x => x.status === currentFilter);

     const totalPages = Math.ceil(items.length / PER_PAGE);
     const start = (currentPage - 1) * PER_PAGE;
     const pageItems = items.slice(start, start + PER_PAGE);

     // Render list with clickable links
     list.innerHTML = pageItems.map(a => {
       const aniUrl = `https://anilist.co/anime/${a.media.id}`;
       return `<a class="anilist-entry-link" href="${aniUrl}" target="_blank" rel="noopener">
         <div class="anilist-cover"><img src="${a.media.coverImage.large}" loading="lazy" alt=""></div>
         <div class="anilist-info">
           <div class="anilist-title">${a.media.title.romaji}</div>
           <div class="anilist-meta">${a.progress||0}/${a.media.episodes||"?"} episodes</div>
         </div>
         <div class="anilist-score">★ ${a.score||0}</div>
       </a>`;
     }).join('');

     // Animate entries in
     list.querySelectorAll('.anilist-entry-link').forEach((el, i) => {
       el.style.opacity = '0';
       el.style.transform = 'translateY(14px) scale(.985)';
       el.style.transition = `opacity 0.34s ease ${i*0.05}s, transform 0.34s cubic-bezier(.22,1,.36,1) ${i*0.05}s`;
       requestAnimationFrame(() => {
         el.style.opacity = '1';
         el.style.transform = 'translateY(0) scale(1)';
       });
     });

     // Render pagination
     const pag = document.getElementById('anilist-pagination');
     if (pag) {
       if (totalPages <= 1) { pag.innerHTML = ''; return; }
       let btns = '';
       // Prev
       btns += `<button class="ani-page-btn" ${currentPage===1?'disabled':''} onclick="window.animateAniPageSwap(${currentPage-1})">‹</button>`;
       // Page numbers (show up to 5 around current)
       const range = 2;
       for (let p = 1; p <= totalPages; p++) {
         if (p === 1 || p === totalPages || (p >= currentPage - range && p <= currentPage + range)) {
           btns += `<button class="ani-page-btn${p===currentPage?' active':''}" onclick="window.animateAniPageSwap(${p})">${p}</button>`;
         } else if (p === currentPage - range - 1 || p === currentPage + range + 1) {
           btns += `<span class="ani-page-info">…</span>`;
         }
       }
       // Next
       btns += `<button class="ani-page-btn" ${currentPage===totalPages?'disabled':''} onclick="window.animateAniPageSwap(${currentPage+1})">›</button>`;
       pag.innerHTML = btns;
     }
   };

   window.renderAniFilter('ALL', 1);

   document.querySelectorAll('.anilist-tab').forEach(btn => {
     btn.onclick = () => {
       document.querySelectorAll('.anilist-tab').forEach(x => x.classList.remove('active'));
       btn.classList.add('active');
       window.renderAniFilter(btn.dataset.filter, 1);
     };
   });
  } catch(e) {
    const mockAnime = [
      { id: 1, title: "Steins;Gate", ep: "24/24", score: "9.1", img: "https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx9253-7pdcfzdwSatL.jpg" },
      { id: 2, title: "Cyberpunk: Edgerunners", ep: "10/10", score: "8.9", img: "https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx127230-FlochcLuR84g.png" },
      { id: 3, title: "Sousou no Frieren", ep: "28/28", score: "9.3", img: "https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx154587-n1fmjWJ2YcBP.jpg" },
      { id: 4, title: "Jujutsu Kaisen", ep: "24/24", score: "8.8", img: "https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx113415-bbBWj4pEFseh.jpg" },
      { id: 5, title: "Cowboy Bebop", ep: "26/26", score: "8.9", img: "https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx1-hBA1Hk3s1Bpa.png" }
    ];
    if (list) {
      list.innerHTML = mockAnime.map(a => `<div class="anilist-entry-link">
         <div class="anilist-cover"><img src="${a.img}" loading="lazy" alt=""></div>
         <div class="anilist-info">
           <div class="anilist-title">${a.title}</div>
           <div class="anilist-meta">${a.ep} episodes</div>
         </div>
         <div class="anilist-score">★ ${a.score}</div>
       </div>`).join('');
    }
    const mins = document.getElementById('anilist-mins');
    if (mins) mins.innerHTML = `142 anime &nbsp;•&nbsp; 3,420 episodes &nbsp;•&nbsp; 1,380 hrs watched`;
  }
}
window.addEventListener('load',()=>setTimeout(rebuildAni, 900), { once:true });
})();

