// ── STARK MUSIC ENGINE (Single Song: in the pool by kensuke ushio) ──
const YOUTUBE_VIDEO_ID = 'rOWDEfnWx5s';

const singleTrack = {
  title: "in the pool",
  artist: "kensuke ushio"
};

const fallbackAudioUrl = null;

let ytPlayerObj = null;
let htmlAudioObj = null;
let isPlayingMusic = false;
let currentVol = 70; // 70% volume
let progressTimer = null;
let progressPct = 0;
let useHtmlFallback = false;

function initMusicEngine() {
  const tag = document.createElement('script');
  tag.src = "https://www.youtube.com/iframe_api";
  const firstScriptTag = document.getElementsByTagName('script')[0];
  if (firstScriptTag && firstScriptTag.parentNode) {
    firstScriptTag.parentNode.insertBefore(tag, firstScriptTag);
  }

  if (fallbackAudioUrl) {
  htmlAudioObj = new Audio(fallbackAudioUrl);
}

  window.onYouTubeIframeAPIReady = function() {
    try {
      ytPlayerObj = new YT.Player('yt-music-iframe', {
        height: '10', width: '10',
        videoId: YOUTUBE_VIDEO_ID,
        playerVars: {
          autoplay: 0, controls: 0, disablekb: 1, fs: 0, playsinline: 1, loop: 1, playlist: YOUTUBE_VIDEO_ID
        },
        events: {
          'onReady': function(e) { e.target.setVolume(currentVol); },
          'onStateChange': onYTStateChange,
          'onError': function() { useHtmlFallback = true; }
        }
      });
    } catch(err) {
      useHtmlFallback = true;
    }
  };
}

function onYTStateChange(event) {
  if (event.data === YT.PlayerState.PLAYING) {
    isPlayingMusic = true;
    updatePlayerUI();
  } else if (event.data === YT.PlayerState.ENDED) {
    if (ytPlayerObj && ytPlayerObj.playVideo) ytPlayerObj.playVideo();
  } else if (event.data === YT.PlayerState.PAUSED) {
    isPlayingMusic = false;
    updatePlayerUI();
  }
}

function togglePlay() {
  isPlayingMusic = !isPlayingMusic;
  updatePlayerUI();

  if (isPlayingMusic) {
    if (!useHtmlFallback && ytPlayerObj && typeof ytPlayerObj.playVideo === 'function') {
      try {
        ytPlayerObj.playVideo();
        ytPlayerObj.setVolume(currentVol);
      } catch(e) { useHtmlFallback = true; }
    } else { useHtmlFallback = true; }

    setTimeout(function() {
      if (isPlayingMusic && (!ytPlayerObj || ytPlayerObj.getPlayerState?.() !== 1)) {
        useHtmlFallback = true;
        if (htmlAudioObj) {
          htmlAudioObj.play().catch(function(){ console.log("Audio autoplay blocked"); });
        }
      }
    }, 1000);

    if (useHtmlFallback && htmlAudioObj) {
      htmlAudioObj.play().catch(function(){ console.log("Audio autoplay blocked"); });
    }
    startProgressAnim();
  } else {
    if (ytPlayerObj && typeof ytPlayerObj.pauseVideo === 'function') {
      try { ytPlayerObj.pauseVideo(); } catch(e){}
    }
    if (htmlAudioObj) htmlAudioObj.pause();
    stopProgressAnim();
  }
}

function updatePlayerUI() {
  const tbDisc = document.getElementById('tb-music-disc');
  const spVinyl = document.getElementById('sp-vinyl');
  const eqBars = document.getElementById('tb-eq-bars');
  const threeDots = document.getElementById('tb-three-dots');
  const playIcon = document.getElementById('sp-icon-play');
  const pauseIcon = document.getElementById('sp-icon-pause');

  if (isPlayingMusic) {
    if (tbDisc) tbDisc.classList.add('spinning');
    if (spVinyl) spVinyl.classList.add('spinning');
    if (eqBars) eqBars.style.display = 'flex';
    if (threeDots) threeDots.style.display = 'none';
    if (playIcon) playIcon.style.display = 'none';
    if (pauseIcon) pauseIcon.style.display = 'block';
  } else {
    if (tbDisc) tbDisc.classList.remove('spinning');
    if (spVinyl) spVinyl.classList.remove('spinning');
    if (eqBars) eqBars.style.display = 'none';
    if (threeDots) threeDots.style.display = 'flex';
    if (playIcon) playIcon.style.display = 'block';
    if (pauseIcon) pauseIcon.style.display = 'none';
  }
}

function nextTrack() {
  if (ytPlayerObj && ytPlayerObj.seekTo) ytPlayerObj.seekTo(0);
  if (htmlAudioObj) htmlAudioObj.currentTime = 0;
  progressPct = 0;
}

function prevTrack() {
  if (ytPlayerObj && ytPlayerObj.seekTo) ytPlayerObj.seekTo(0);
  if (htmlAudioObj) htmlAudioObj.currentTime = 0;
  progressPct = 0;
}

function toggleMusicPanel() {
  const panel = document.getElementById('slide-music-player');
  if (panel) panel.classList.toggle('active');
}

function changeVolume(val) {
  currentVol = parseInt(val);
  document.getElementById('sp-vol-val').textContent = currentVol + '%';
  if (ytPlayerObj && typeof ytPlayerObj.setVolume === 'function') {
    try { ytPlayerObj.setVolume(currentVol); } catch(e){}
  }
  if (htmlAudioObj) htmlAudioObj.volume = currentVol / 100;
}

function startProgressAnim() {
  stopProgressAnim();
  // Use rAF instead of setInterval — frame-synced, no jank
  let lastT = 0;
  function tick(now) {
    if (now - lastT >= 500) {
      lastT = now;
      progressPct = (progressPct + 0.3) % 100;
      const p1 = document.getElementById('sp-progress-fill');
      if (p1) p1.style.width = progressPct + '%';
    }
    if (progressTimer !== null) progressTimer = requestAnimationFrame(tick);
  }
  progressTimer = requestAnimationFrame(tick);
}

function stopProgressAnim() {
  if (progressTimer) { cancelAnimationFrame(progressTimer); progressTimer = null; }
}


window.toggleMusicPanel=toggleMusicPanel;
function scrollToSection(e, secId) {
  if (e) e.preventDefault();
  const el = document.getElementById(secId);
  if (el) {
    const offset = 70;
    const bodyRect = document.body.getBoundingClientRect().top;
    const elementRect = el.getBoundingClientRect().top;
    const elementPosition = elementRect - bodyRect;
    const offsetPosition = elementPosition - offset;

    window.scrollTo({
      top: offsetPosition,
      behavior: 'smooth'
    });
  }
}

// Active section highlight — throttled with rAF so it never blocks scroll
(function(){
  const sections = ['hero', 'about', 'skills', 'projects', 'contact'];
  const btns = {};
  sections.forEach(id => { btns[id] = document.querySelector(`.tb-icon-btn[data-section="${id}"]`); });
  const allBtns = document.querySelectorAll('.tb-icon-btn');
  let ticking = false;

  function updateActive() {
    ticking = false;
    const scrollPos = window.scrollY + 200;
    for (let i = sections.length - 1; i >= 0; i--) {
      const sec = document.getElementById(sections[i]);
      if (sec && sec.offsetTop <= scrollPos) {
        allBtns.forEach(b => b.classList.remove('active'));
        if (btns[sections[i]]) btns[sections[i]].classList.add('active');
        break;
      }
    }
  }

  window.addEventListener('scroll', () => {
    if (!ticking) { ticking = true; requestAnimationFrame(updateActive); }
  }, { passive: true });
})();

document.addEventListener('DOMContentLoaded',()=>{
  let booted=false;
  const boot=()=>{ if(booted) return; booted=true; try{ initMusicEngine(); }catch(e){} };
  window.__bootMusicEngine = boot;
  document.querySelector('.topbar-music-widget')?.addEventListener('pointerdown', boot, { once:true, passive:true });
  document.querySelector('.tb-music-icon')?.addEventListener('pointerdown', boot, { once:true, passive:true });
  document.querySelector('.tb-music-text')?.addEventListener('pointerdown', boot, { once:true, passive:true });
  document.querySelector('.tb-music-dots')?.addEventListener('pointerdown', boot, { once:true, passive:true });
});

