/* ===== script-block-7 ===== */
document.addEventListener('DOMContentLoaded',()=>{
const SRC='https://raw.githubusercontent.com/4nx3b/4nx3b/main/09.%20in%20the%20pool.mp3';
let audio=document.querySelector('audio');
if(!audio){
 audio=document.createElement('audio');
 document.body.appendChild(audio);
}
audio.src=SRC;
audio.preload='none';
audio.crossOrigin='anonymous';

// Override play/pause to always use this audio
document.querySelectorAll('[data-play],.sp-play-btn,.tb-music-icon').forEach(el=>{
 el.addEventListener('click',e=>{
   e.stopPropagation();
   if(audio.paused){audio.play().catch(()=>{});}
   else{audio.pause();}
 },true);
});

// Format seconds into M:SS
function formatTime(secs) {
  if (isNaN(secs) || !isFinite(secs) || secs <= 0) return '0:00';
  const m = Math.floor(secs / 60);
  const s = Math.floor(secs % 60);
  return `${m}:${s.toString().padStart(2, '0')}`;
}

// Disable old dummy progress animations
window.startProgressAnim = function(){};
window.stopProgressAnim = function(){};

function updateAudioUI() {
  const fill = document.getElementById('sp-progress-fill');
  const currEl = document.getElementById('sp-curr-time');
  const durEl = document.getElementById('sp-duration');
  if (durEl && audio.duration && !isNaN(audio.duration)) {
    durEl.textContent = formatTime(audio.duration);
  }
  if (currEl && !isNaN(audio.currentTime)) {
    currEl.textContent = formatTime(audio.currentTime);
  }
  if (fill && audio.duration && !isNaN(audio.duration)) {
    const pct = (audio.currentTime / audio.duration) * 100;
    fill.style.width = pct + '%';
  }
}

// Throttle timeupdate to rAF to avoid mid-frame style mutations
let _audioRaf = 0;
audio.addEventListener('loadedmetadata', updateAudioUI);
audio.addEventListener('durationchange', updateAudioUI);
audio.addEventListener('timeupdate', () => {
  if (!_audioRaf) _audioRaf = requestAnimationFrame(() => { _audioRaf = 0; updateAudioUI(); });
});

// UI state syncing (disc spin & play/pause icon)
audio.addEventListener('play', () => {
  const tbDisc = document.getElementById('tb-music-disc');
  const spVinyl = document.getElementById('sp-vinyl');
  const eqBars = document.getElementById('tb-eq-bars');
  const threeDots = document.getElementById('tb-three-dots');
  const playIcon = document.getElementById('sp-icon-play');
  const pauseIcon = document.getElementById('sp-icon-pause');
  if(tbDisc) tbDisc.classList.add('spinning');
  if(spVinyl) spVinyl.classList.add('spinning');
  if(eqBars) eqBars.style.display = 'flex';
  if(threeDots) threeDots.style.display = 'none';
  if(playIcon) playIcon.style.display = 'none';
  if(pauseIcon) pauseIcon.style.display = 'block';
});

audio.addEventListener('pause', () => {
  const tbDisc = document.getElementById('tb-music-disc');
  const spVinyl = document.getElementById('sp-vinyl');
  const eqBars = document.getElementById('tb-eq-bars');
  const threeDots = document.getElementById('tb-three-dots');
  const playIcon = document.getElementById('sp-icon-play');
  const pauseIcon = document.getElementById('sp-icon-pause');
  if(tbDisc) tbDisc.classList.remove('spinning');
  if(spVinyl) spVinyl.classList.remove('spinning');
  if(eqBars) eqBars.style.display = 'none';
  if(threeDots) threeDots.style.display = 'flex';
  if(playIcon) playIcon.style.display = 'block';
  if(pauseIcon) pauseIcon.style.display = 'none';
});

// Interactive seeking on click
const progBar = document.getElementById('sp-progress-bar');
if (progBar) {
  progBar.addEventListener('click', (e) => {
    if (!audio.duration || isNaN(audio.duration)) return;
    const rect = progBar.getBoundingClientRect();
    const clickPos = Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width));
    audio.currentTime = clickPos * audio.duration;
    updateAudioUI();
  });
}
});

