// Close the mini player whenever the user scrolls or taps/clicks outside it.
document.addEventListener('DOMContentLoaded', () => {
  const panel = document.getElementById('slide-music-player');
  if (!panel) return;

  const closeMiniPlayer = () => panel.classList.remove('active');

  window.addEventListener('scroll', closeMiniPlayer, { passive: true });
  window.addEventListener('wheel', closeMiniPlayer, { passive: true });
  window.addEventListener('touchmove', closeMiniPlayer, { passive: true });

  document.addEventListener('pointerdown', (e) => {
    if (!panel.classList.contains('active')) return;
    if (panel.contains(e.target)) return;
    if (e.target.closest('.topbar-music-widget')) return;
    closeMiniPlayer();
  }, { passive: true });
});

/* ===== script-block-10 ===== */
// Clear mobile sticky hover/focus from the music pill as soon as scrolling starts.
document.addEventListener('DOMContentLoaded', () => {
  let hoverResetTimer = 0;
  const resetTopbarMusicHover = () => {
    document.body.classList.add('suppress-topbar-hover');
    const active = document.activeElement;
    if (active && typeof active.blur === 'function') active.blur();
    clearTimeout(hoverResetTimer);
    hoverResetTimer = setTimeout(() => {
      document.body.classList.remove('suppress-topbar-hover');
    }, 900);
  };

  window.addEventListener('scroll', resetTopbarMusicHover, { passive: true });
  window.addEventListener('touchmove', resetTopbarMusicHover, { passive: true });
  window.addEventListener('wheel', resetTopbarMusicHover, { passive: true });
});

/* ===== script-block-11 ===== */
// Autoplay the site music with a gentle fade-in to 20% volume.
// Note: some mobile browsers block audible autoplay; if blocked, this retries on the first user interaction.
(function(){
  const SRC = 'https://raw.githubusercontent.com/4nx3b/4nx3b/main/09.%20in%20the%20pool.mp3';
  const START_VOLUME = 0.01;
  const TARGET_VOLUME = 0.70;
  const FADE_MS = 5200;
  let fadeRaf = 0;
  let armedFallback = false;

  function getAudio(){
    let audio = document.querySelector('audio');
    if(!audio){
      audio = document.createElement('audio');
      document.body.appendChild(audio);
    }
    if(audio.src !== SRC){
      audio.src = SRC;
    }
    audio.preload = 'none';
    audio.crossOrigin = 'anonymous';
    audio.loop = true;
    return audio;
  }

  function setVolumeUI(percent){
    const slider = document.getElementById('sp-vol-slider');
    const label = document.getElementById('sp-vol-val');
    if(slider) slider.value = String(percent);
    if(label) label.textContent = percent + '%';
    try { if (typeof changeVolume === 'function') changeVolume(percent); } catch(e) {}
  }

  function syncPlayingUI(){
    const tbDisc = document.getElementById('tb-music-disc');
    const spVinyl = document.getElementById('sp-vinyl');
    const eqBars = document.getElementById('tb-eq-bars');
    const threeDots = document.getElementById('tb-three-dots');
    const playIcon = document.getElementById('sp-icon-play');
    const pauseIcon = document.getElementById('sp-icon-pause');
    if(tbDisc) tbDisc.classList.add('spinning');
    if(spVinyl) spVinyl.classList.add('spinning');
    if(eqBars) eqBars.style.display = 'flex';
    if(threeDots) threeDots.style.display = 'none';
    if(playIcon) playIcon.style.display = 'none';
    if(pauseIcon) pauseIcon.style.display = 'block';
  }

  function fadeIn(audio){
    cancelAnimationFrame(fadeRaf);
    const start = performance.now();
    audio.volume = START_VOLUME;
    setVolumeUI(70);
    syncPlayingUI();

    const tick = (now) => {
      const t = Math.min((now - start) / FADE_MS, 1);
      const eased = 1 - Math.pow(1 - t, 3);
      audio.volume = START_VOLUME + (TARGET_VOLUME - START_VOLUME) * eased;
      if(t < 1) fadeRaf = requestAnimationFrame(tick);
      else audio.volume = TARGET_VOLUME;
    };
    fadeRaf = requestAnimationFrame(tick);
  }

  function attemptAutoplay(){
    const audio = getAudio();
    audio.muted = false;
    audio.volume = START_VOLUME;
    const playAttempt = audio.play();
    if(playAttempt && typeof playAttempt.then === 'function'){
      playAttempt.then(() => fadeIn(audio)).catch(() => armFallback());
    } else {
      fadeIn(audio);
    }
  }

  function armFallback(){
    if(armedFallback) return;
    armedFallback = true;
    const once = () => {
      window.removeEventListener('pointerdown', once, true);
      window.removeEventListener('touchstart', once, true);
      window.removeEventListener('keydown', once, true);
      window.removeEventListener('scroll', once, true);
      attemptAutoplay();
    };
    window.addEventListener('pointerdown', once, true);
    window.addEventListener('touchstart', once, true);
    window.addEventListener('keydown', once, true);
    window.addEventListener('scroll', once, true);
  }

  document.addEventListener('DOMContentLoaded', () => {
    setVolumeUI(70);
    armFallback();
  });
})();

