// Static inner pages: remove inline animation styles added by existing render code.
// Does not touch header/topbar, intro overlay, or #hero.
(function(){
  function clearInnerPageMotion(root){
    const scope = root || document;
    const nodes = scope.querySelectorAll ? scope.querySelectorAll(
      'body > .gradient-line ~ section .fade-in, body > .gradient-line ~ section .slide-in, body > .gradient-line ~ section .fade-up,' +
      'body > .gradient-line ~ section .project-card, body > .gradient-line ~ section .interest-card, body > .gradient-line ~ section .rom-card,' +
      'body > .gradient-line ~ section .media-panel, body > .gradient-line ~ section .skill-row-entry, body > .gradient-line ~ section .anilist-entry-link,' +
      'body > .gradient-line ~ section .lastfm-track, body > .gradient-line ~ section .lastfm-artist-row, body > .gradient-line ~ section .contact-link-item, .online-presence, footer'
    ) : [];
    nodes.forEach(function(el){
      el.style.opacity = '1';
      el.style.transform = 'none';
      el.style.transition = 'none';
      el.style.animation = 'none';
      el.classList.add('visible');
    });
  }
  document.addEventListener('DOMContentLoaded', function(){
    clearInnerPageMotion(document);
    ['skill-list','anilist-list','lastfm-tracks','lastfm-artists','lastfm-recent','projects-container'].forEach(function(id){
      const el = document.getElementById(id);
      if (!el) return;
      new MutationObserver(function(){ clearInnerPageMotion(document); }).observe(el, {childList:true, subtree:true});
    });
  });
  window.addEventListener('load', function(){ clearInnerPageMotion(document); }, {once:true});
})();

