// Alignment fixes + routed playable games + restored animated hero headline.
(function(){
  function ready(fn){ if(document.readyState !== 'loading') fn(); else document.addEventListener('DOMContentLoaded', fn); }
  function showHome(){ document.body.classList.remove('gx-game-mode'); history.replaceState(null,'','#hero'); window.scrollTo({top:0,behavior:'smooth'}); }
  function showGames(){ document.body.classList.add('gx-game-mode'); history.replaceState(null,'','#games'); window.scrollTo({top:0,behavior:'smooth'}); }
  window.gxShowHome = showHome; window.gxShowGames = showGames;

  function restoreHeadline(){
    const hero=document.getElementById('hero'); if(!hero) return;
    let h=hero.querySelector('.hero-h1');
    if(!h){ h=document.createElement('h1'); h.className='hero-h1'; hero.insertBefore(h, hero.querySelector('.gx-welcome-card')||hero.firstChild); }
    h.innerHTML='<span class="hero-h1-gif-text">Building Android<br>beyond stock</span>';
  }

  function wireHomeGame(){
    const chips=[...document.querySelectorAll('.gx-hero-actions .gx-chip')];
    let btn=chips.find(a=>a.classList.contains('gx-game-home') || /game|🎮/i.test(a.textContent));
    if(!btn){ btn=chips.find(a=>/about\s*me/i.test(a.textContent)); }
    if(btn){
      btn.classList.add('gx-game-home','round'); btn.href='javascript:void(0)'; btn.innerHTML='🎮<span>Games</span>'; btn.title='Games';
      btn.onclick=function(e){ e.preventDefault(); showGames(); };
    }
  }

  function removeOldGames(){ const old=document.getElementById('gx-games'); if(old) old.style.display='none'; }

  function ensureGamePage(){
    if(document.getElementById('gx-game-page')) return;
    const sec=document.createElement('section'); sec.id='gx-game-page';
    const games=[
      ['snake','♞','Snake','Classic game. High chance of self-sabotage.'],
      ['pong','◉','Ping Pong','You vs an AI paddle. First to 5 wins.'],
      ['quiz','▱','Roast Quiz','A personality test but every answer is a personal attack.'],
      ['flappy','⌁','Flappy','Infuriating physics. Avoid the pipes.'],
      ['mines','⚑','Minesweeper','Classic logic. Avoid the mines.'],
      ['reaction','◌','Reaction Test','Click when it turns green.'],
      ['dodge','⌖','Dodge','Survive against angry geometry.']
    ];
    sec.innerHTML=`<button class="gx-game-return" type="button" onclick="gxShowHome()">← Return</button><h1 class="gx-game-page-title">playground.</h1><p class="gx-game-page-sub">games. roasts. questionable life choices.</p><div class="gx-game-route-list">${games.map(g=>`<article class="gx-play-card" id="game-${g[0]}"><div class="gx-play-card-icon">${g[1]}</div><h3>${g[2]}</h3><p>${g[3]}</p><button class="gx-play-btn" data-game="${g[0]}">Play →</button><div class="gx-play-area"></div></article>`).join('')}</div>`;
    document.body.insertBefore(sec, document.querySelector('footer'));
    sec.addEventListener('click', e=>{ const b=e.target.closest('.gx-play-btn'); if(!b) return; startGame(b.dataset.game, b.closest('.gx-play-card')); });
  }

  function clearArea(card){
    document.querySelectorAll('.gx-play-card').forEach(c=>{ if(c!==card) c.classList.remove('playing'); });
    const area=card.querySelector('.gx-play-area'); card.classList.add('playing'); area.innerHTML=''; return area;
  }

  function startGame(type, card){
    if(type==='snake') return snake(clearArea(card));
    if(type==='pong') return pong(clearArea(card));
    if(type==='quiz') return quiz(clearArea(card));
    if(type==='flappy') return flappy(clearArea(card));
    if(type==='mines') return mines(clearArea(card));
    if(type==='reaction') return reaction(clearArea(card));
    if(type==='dodge') return dodge(clearArea(card));
  }

  function makeCanvas(area,w=320,h=320){ area.innerHTML='<canvas class="gx-game-canvas" width="'+w+'" height="'+h+'"></canvas><div class="gx-game-status"></div>'; return [area.querySelector('canvas'), area.querySelector('.gx-game-status')]; }

  function snake(area){
    const [cv,st]=makeCanvas(area); const ctx=cv.getContext('2d'); let n=16, cell=cv.width/n, snake=[{x:8,y:8}], dir={x:1,y:0}, food={x:4,y:4}, alive=true, score=0;
    area.insertAdjacentHTML('beforeend','<div class="gx-game-controls"><span></span><button data-d="up">↑</button><span></span><button data-d="left">←</button><button data-d="down">↓</button><button data-d="right">→</button></div>');
    function set(d){ if(d==='up'&&dir.y!==1)dir={x:0,y:-1}; if(d==='down'&&dir.y!==-1)dir={x:0,y:1}; if(d==='left'&&dir.x!==1)dir={x:-1,y:0}; if(d==='right'&&dir.x!==-1)dir={x:1,y:0}; }
    area.querySelectorAll('[data-d]').forEach(b=>b.onclick=()=>set(b.dataset.d));
    window.onkeydown=e=>set({ArrowUp:'up',ArrowDown:'down',ArrowLeft:'left',ArrowRight:'right'}[e.key]);
    function draw(){ctx.fillStyle='#080808';ctx.fillRect(0,0,cv.width,cv.height);ctx.fillStyle='#fffdd1';snake.forEach(p=>ctx.fillRect(p.x*cell+1,p.y*cell+1,cell-2,cell-2));ctx.fillStyle='#20bf77';ctx.fillRect(food.x*cell+2,food.y*cell+2,cell-4,cell-4);st.textContent=alive?'Score '+score:'Game over — press Play again';}
    function tick(){ if(!alive) return draw(); const h={x:snake[0].x+dir.x,y:snake[0].y+dir.y}; if(h.x<0||h.y<0||h.x>=n||h.y>=n||snake.some(p=>p.x===h.x&&p.y===h.y)){alive=false;return draw();} snake.unshift(h); if(h.x===food.x&&h.y===food.y){score++;food={x:Math.floor(Math.random()*n),y:Math.floor(Math.random()*n)}}else snake.pop(); draw(); setTimeout(tick,140);} tick();
  }

  function pong(area){
    const [cv,st]=makeCanvas(area,360,240); const ctx=cv.getContext('2d'); let py=90, ay=90, bx=180, by=120, vx=3, vy=2, ps=0, as=0;
    function move(y){ const r=cv.getBoundingClientRect(); py=Math.max(0,Math.min(180,(y-r.top)/r.height*cv.height-30)); }
    cv.onpointermove=e=>move(e.clientY); cv.onpointerdown=e=>move(e.clientY);
    function loop(){ ay+=(by-ay-30)*.06; bx+=vx; by+=vy; if(by<0||by>240)vy*=-1; if(bx<18&&by>py&&by<py+60){vx=Math.abs(vx)+.15} if(bx>342&&by>ay&&by<ay+60){vx=-Math.abs(vx)-.15} if(bx<0){as++;bx=180;vx=3} if(bx>360){ps++;bx=180;vx=-3} ctx.fillStyle='#080808';ctx.fillRect(0,0,360,240);ctx.fillStyle='#fffdd1';ctx.fillRect(10,py,8,60);ctx.fillRect(342,ay,8,60);ctx.beginPath();ctx.arc(bx,by,7,0,7);ctx.fill();st.textContent=`You ${ps} · AI ${as}`; if(ps<5&&as<5)requestAnimationFrame(loop); else st.textContent+=(ps>as?' — you win':' — AI wins');} loop();
  }

  function quiz(area){ const qs=[['Your debugging style?',['Scientific','Panic console logs','Blame vendor blobs'],['Responsible. Suspicious.','A classic gremlin.','Correct, honestly.']],['Pick a superpower.',['Fastboot never fails','Infinite battery','No merge conflicts'],['Impossible dream.','Rooted monk energy.','Too powerful.']]]; let i=0; function render(){let q=qs[i%qs.length];area.innerHTML='<div class="gx-game-status">'+q[0]+'</div><div class="gx-quiz-options">'+q[1].map((o,k)=>'<button data-k="'+k+'">'+o+'</button>').join('')+'</div>';area.querySelectorAll('button').forEach(b=>b.onclick=()=>{area.querySelector('.gx-game-status').textContent=q[2][+b.dataset.k];setTimeout(()=>{i++;render()},1200)});} render(); }

  function flappy(area){ const [cv,st]=makeCanvas(area,320,420); const ctx=cv.getContext('2d'); let y=210, v=0, pipes=[], t=0, score=0, alive=true; function flap(){v=-7} cv.onclick=flap; area.onclick=e=>{if(e.target===area)flap()}; function loop(){ if(!alive){st.textContent='Game over · score '+score;return;} t++; v+=.45;y+=v;if(t%85===0){let gap=120, top=40+Math.random()*190;pipes.push({x:320,top,gap,sc:false})} pipes.forEach(p=>p.x-=2.4); pipes=pipes.filter(p=>p.x>-50); for(const p of pipes){ if(52>p.x&&52<p.x+42&&(y<p.top||y>p.top+p.gap))alive=false; if(!p.sc&&p.x<52){score++;p.sc=true} } if(y<0||y>420)alive=false; ctx.fillStyle='#080808';ctx.fillRect(0,0,320,420);ctx.fillStyle='#fffdd1';ctx.beginPath();ctx.arc(52,y,12,0,7);ctx.fill();ctx.fillStyle='#20bf77';pipes.forEach(p=>{ctx.fillRect(p.x,0,42,p.top);ctx.fillRect(p.x,p.top+p.gap,42,420)});st.textContent='Score '+score+' · tap/click to flap';requestAnimationFrame(loop)} loop(); }

  function mines(area){ const size=8, mines=new Set(); while(mines.size<10)mines.add(Math.floor(Math.random()*64)); area.innerHTML='<div class="gx-game-status">Find safe cells. Avoid mines.</div><div class="gx-mine-grid"></div>'; const grid=area.querySelector('.gx-mine-grid'); for(let i=0;i<64;i++){const b=document.createElement('button');b.className='gx-mine-cell';b.onclick=()=>{ if(mines.has(i)){b.textContent='💣'; area.querySelector('.gx-game-status').textContent='Boom. Game over.'; [...grid.children].forEach((c,j)=>{if(mines.has(j))c.textContent='💣'});} else {let x=i%8,y=Math.floor(i/8),c=0; for(let dx=-1;dx<=1;dx++)for(let dy=-1;dy<=1;dy++){let nx=x+dx,ny=y+dy;if(nx>=0&&ny>=0&&nx<8&&ny<8&&mines.has(ny*8+nx))c++;} b.textContent=c||'·'; b.disabled=true;} }; grid.appendChild(b);} }

  function reaction(area){ area.innerHTML='<div class="gx-react-box">Wait...</div><div class="gx-game-status">Click only when green.</div>'; const box=area.querySelector('.gx-react-box'), st=area.querySelector('.gx-game-status'); let start=0, ready=false; setTimeout(()=>{ready=true;start=performance.now();box.classList.add('ready');box.textContent='CLICK!'},900+Math.random()*2200); box.onclick=()=>{ if(!ready){st.textContent='Too early. Impulsive.';return;} st.textContent='Reaction: '+Math.round(performance.now()-start)+'ms'; ready=false;}; }

  function dodge(area){ area.innerHTML='<div class="gx-dodge-wrap"><div class="gx-dodge-player"></div></div><div class="gx-game-status">Drag/click to move. Survive.</div>'; const wrap=area.querySelector('.gx-dodge-wrap'), pl=area.querySelector('.gx-dodge-player'), st=area.querySelector('.gx-game-status'); let x=40,y=120,alive=true,start=performance.now(),en=[]; function move(e){const r=wrap.getBoundingClientRect();x=(e.clientX-r.left)/r.width*wrap.clientWidth;y=(e.clientY-r.top)/r.height*wrap.clientHeight;} wrap.onpointermove=move; wrap.onpointerdown=move; function loop(){ if(!alive)return; if(Math.random()<.05){let d=document.createElement('div');d.className='gx-dodge-enemy';d.style.left=wrap.clientWidth+'px';d.style.top=Math.random()*(wrap.clientHeight-24)+'px';wrap.appendChild(d);en.push({el:d,x:wrap.clientWidth,y:parseFloat(d.style.top),v:2+Math.random()*3});} pl.style.left=x+'px';pl.style.top=y+'px'; en.forEach(o=>{o.x-=o.v;o.el.style.left=o.x+'px'; if(Math.abs(o.x-x)<22&&Math.abs(o.y-y)<22){alive=false;st.textContent='Hit. Survived '+Math.round((performance.now()-start)/1000)+'s';}}); en=en.filter(o=>o.x>-30); st.textContent='Survive: '+Math.round((performance.now()-start)/1000)+'s'; requestAnimationFrame(loop);} loop(); }

  ready(function(){
    restoreHeadline(); wireHomeGame(); removeOldGames(); ensureGamePage();
    if(location.hash==='#games') showGames();
    window.addEventListener('hashchange',()=>{ if(location.hash==='#games') showGames(); });
  });
})();

/* ===== ultimate-clean-dark-stable-script ===== */
(function(){
  const reze = ["data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,"];
  function ready(fn){document.readyState==='loading'?document.addEventListener('DOMContentLoaded',fn):fn();}
  function forceDarkOnly(){
    document.documentElement.classList.remove('light');
    try{localStorage.setItem('theme','dark')}catch(e){}
    window.toggleTheme=function(){document.documentElement.classList.remove('light');return false;};
    const btn=document.getElementById('theme-toggle-btn'); if(btn) btn.remove();
  }
  function installRezeBackground(){
    const box=document.querySelector('.gx-reze-slideshow'); if(!box) return false;
    box.innerHTML='';
    box.dataset.ultimateReze='1';
    if(!box.dataset.rezeIndex) box.dataset.rezeIndex='0';
    const idx=Number(box.dataset.rezeIndex||0)%reze.length;
    box.style.setProperty('background-image','url("'+reze[idx]+'")','important');
    return true;
  }
  function startRezeLoop(){
    if(window.__ultimateRezeLoop) clearInterval(window.__ultimateRezeLoop);
    window.__ultimateRezeLoop=setInterval(()=>{
      const box=document.querySelector('.gx-reze-slideshow'); if(!box) return;
      const next=(Number(box.dataset.rezeIndex||0)+1)%reze.length;
      box.dataset.rezeIndex=String(next);
      box.style.opacity='.72';
      setTimeout(()=>{box.style.setProperty('background-image','url("'+reze[next]+'")','important'); box.style.opacity='1';},180);
    },4200);
  }
  function stabilizeUi(){
    document.querySelectorAll('.fade-in,.gx-welcome-card,.media-panel,.lastfm-stats-header,.rom-card,.interest-card,.contact-form-wrap,.online-presence-list,.gx-widget-card,.gx-time-inner,.gx-reze-slideshow,.gx-play-card,footer').forEach(el=>{
      el.style.opacity='1'; el.style.transform='none'; el.style.filter='none'; el.style.animation='none';
    });
    const lf=document.querySelector('.lastfm-profile-link'); if(lf){lf.style.color='#f5f2e9'; lf.style.background='rgba(255,255,255,.055)';}
  }
  function musicFallback(){
    // Keep the original play/pause behaviour. Do not inject a second hidden YouTube iframe,
    // because that causes overlapping playback and restarts when the topbar thumbnail is clicked.
    if(window.__ultimateMusicPatched) return; window.__ultimateMusicPatched=true;
    const old=window.togglePlay;
    window.togglePlay=function(){ if(typeof old==='function') { try{old();}catch(e){} } };
  }
  ready(()=>{
    forceDarkOnly(); installRezeBackground(); startRezeLoop(); stabilizeUi(); musicFallback();
    let n=0; const t=setInterval(()=>{forceDarkOnly(); installRezeBackground(); stabilizeUi(); if(++n>120) clearInterval(t);},100);
    const mo=new MutationObserver(()=>{forceDarkOnly(); installRezeBackground(); stabilizeUi();});
    mo.observe(document.body,{childList:true,subtree:true});
  });
})();

