  function flappy(card,area){const type='flappy',[cv,ctx,st]=canvas(area,320,420,'Tap canvas to start/flap.');let raf,started=false,alive=true,y=210,v=0,pipes=[],t=0,score=0;function flap(){if(!alive)return;if(!started){started=true;loop()}v=-7}cv.onclick=flap;function loop(){t++;v+=.45;y+=v;if(t%88===0){let top=35+Math.random()*210;pipes.push({x:320,top,gap:122,sc:false})}pipes.forEach(p=>p.x-=2.35);pipes=pipes.filter(p=>p.x>-50);for(const p of pipes){if(52>p.x&&52<p.x+42&&(y<p.top||y>p.top+p.gap))alive=false;if(!p.sc&&p.x<52){score++;p.sc=true}}if(y<0||y>420)alive=false;ctx.fillStyle='#070707';ctx.fillRect(0,0,320,420);ctx.fillStyle='#f5f2e9';ctx.beginPath();ctx.arc(52,y,12,0,7);ctx.fill();ctx.fillStyle='#23d18b';pipes.forEach(p=>{ctx.fillRect(p.x,0,42,p.top);ctx.fillRect(p.x,p.top+p.gap,42,420)});st.textContent='Score '+score;if(alive)raf=requestAnimationFrame(loop);else gameOver(area,card,'Game over · score '+score,type)}activeCleanups.set(area,()=>cancelAnimationFrame(raf));}
