  function dodge(card,area){const type='dodge';area.innerHTML='<div class="final-game-status">Press inside arena to start.</div><div class="final-dodge"><div class="final-player"></div></div>';const wrap=area.querySelector('.final-dodge'),pl=area.querySelector('.final-player'),st=area.querySelector('.final-game-status');let raf,started=false,alive=true,x=36,y=120,en=[],start=0;function move(e){const r=wrap.getBoundingClientRect();x=(e.clientX-r.left)/r.width*wrap.clientWidth;y=(e.clientY-r.top)/r.height*wrap.clientHeight;if(!started){started=true;start=performance.now();loop()}}wrap.onpointerdown=move;wrap.onpointermove=e=>{if(started)move(e)};function loop(){if(!alive)return;if(Math.random()<.045){let d=document.createElement('div');d.className='final-enemy';d.style.left=wrap.clientWidth+'px';d.style.top=Math.random()*(wrap.clientHeight-24)+'px';wrap.appendChild(d);en.push({el:d,x:wrap.clientWidth,y:parseFloat(d.style.top),v:2+Math.random()*3})}pl.style.left=x+'px';pl.style.top=y+'px';en.forEach(o=>{o.x-=o.v;o.el.style.left=o.x+'px';if(Math.abs(o.x-x)<22&&Math.abs(o.y-y)<22){alive=false;gameOver(area,card,'Hit · survived '+Math.round((performance.now()-start)/1000)+'s',type)}});en=en.filter(o=>o.x>-30);st.textContent='Survive '+Math.round((performance.now()-start)/1000)+'s';if(alive)raf=requestAnimationFrame(loop)}activeCleanups.set(area,()=>cancelAnimationFrame(raf));}
