/* ===== USER PATCH: credit-label cleanup + GitHub (4nx3b) profile card ===== */
(function(){
  function ready(fn){ document.readyState==='loading'
    ? document.addEventListener('DOMContentLoaded', fn) : fn(); }

  // --- 1. Strip the "Also inspired by" label, keep the urstark link ---
  function cleanCreditLabels(){
    var card = document.getElementById('site-credit-card');
    if(!card) return false;
    card.querySelectorAll('.site-credit-row').forEach(function(row){
      // Remove the leading <span>...</span> (the label), but only if there's
      // also a link in the row — never touch the "Made with" badges row.
      var first = row.firstElementChild;
      if(first && first.tagName === 'SPAN' && !first.classList.contains('credit-badge')){
        var hasLink = !!row.querySelector('a');
        if(hasLink) first.remove();
      }
    });
    return true;
  }

  // --- 2. GitHub profile card for 4nx3b ---
  var GH_USER = '4nx3b';
  var GH_CACHE_KEY = 'gh-profile-'+GH_USER;
  var GH_CACHE_TTL = 6 * 60 * 60 * 1000; // 6 hours

  function getCachedProfile(){
    try{
      var raw = localStorage.getItem(GH_CACHE_KEY);
      if(!raw) return null;
      var obj = JSON.parse(raw);
      if(!obj || !obj.ts || (Date.now() - obj.ts) > GH_CACHE_TTL) return null;
      return obj.data;
    }catch(e){ return null; }
  }
  function setCachedProfile(data){
    try{ localStorage.setItem(GH_CACHE_KEY, JSON.stringify({ts:Date.now(), data:data})); }catch(e){}
  }

  function escapeHtml(s){ return String(s==null?'':s)
    .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')
    .replace(/"/g,'&quot;').replace(/'/g,'&#39;'); }

  function renderProfileCard(p){
    if(document.getElementById('gh-profile-card')) return;
    var card = document.getElementById('site-credit-card');
    if(!card) return;
    var avatar = p.avatar_url || ('https://github.com/'+GH_USER+'.png');
    var name   = p.name || GH_USER;
    var login  = '@'+GH_USER;
    var bio    = p.bio || '';
    var loc    = p.location || '';
    var repos  = p.public_repos != null ? p.public_repos : '—';
    var foll   = p.followers    != null ? p.followers    : '—';
    var follg  = p.following    != null ? p.following    : '—';

    var html = ''
      + '<div class="gh-head">'
      +   '<img class="gh-avatar" loading="lazy" decoding="async" alt="'+escapeHtml(name)+' avatar" src="'+escapeHtml(avatar)+'&s=128" onerror="this.onerror=null;this.src=\''+escapeHtml(avatar)+'\'">'
      +   '<div>'
      +     '<div class="gh-name">'+escapeHtml(name)+'</div>'
      +     '<div class="gh-login">'+escapeHtml(login)+' · GitHub</div>'
      +   '</div>'
      + '</div>'
      + (bio ? '<div class="gh-bio">'+escapeHtml(bio)+'</div>' : '')
      + '<div class="gh-meta">'
      +   (loc ? '<span>📍 '+escapeHtml(loc)+'</span>' : '')
      +   '<span>🧩 Android · Python · Kotlin</span>'
      + '</div>'
      + '<div class="gh-stats">'
      +   '<div class="gh-stat"><b>'+repos+'</b><small>Repos</small></div>'
      +   '<div class="gh-stat"><b>'+foll+'</b><small>Followers</small></div>'
      +   '<div class="gh-stat"><b>'+follg+'</b><small>Following</small></div>'
      + '</div>'
      + '<a class="gh-cta" href="https://github.com/'+GH_USER+'" target="_blank" rel="noopener">'
      +   '<svg width="14" height="14" viewBox="0 0 16 16" fill="currentColor" aria-hidden="true"><path d="M8 0C3.58 0 0 3.58 0 8a8 8 0 0 0 5.47 7.59c.4.07.55-.17.55-.38v-1.33c-2.22.48-2.69-1.07-2.69-1.07-.36-.92-.89-1.17-.89-1.17-.72-.49.06-.48.06-.48.8.06 1.22.82 1.22.82.71 1.22 1.87.87 2.33.66.07-.52.28-.87.5-1.07-1.78-.2-3.64-.89-3.64-3.95 0-.87.31-1.59.82-2.15-.08-.2-.36-1.02.08-2.13 0 0 .67-.21 2.2.82a7.66 7.66 0 0 1 4 0c1.53-1.03 2.2-.82 2.2-.82.44 1.11.16 1.93.08 2.13.51.56.82 1.28.82 2.15 0 3.07-1.87 3.75-3.65 3.95.29.25.54.74.54 1.49v2.21c0 .21.15.46.55.38A8 8 0 0 0 16 8c0-4.42-3.58-8-8-8z"/></svg>'
      +   'Visit github.com/'+GH_USER
      + '</a>';

    var section = document.createElement('section');
    section.id = 'gh-profile-card';
    section.setAttribute('aria-label', 'GitHub profile · '+GH_USER);
    section.innerHTML = html;
    card.insertAdjacentElement('afterend', section);
  }

  function fetchProfile(){
    var cached = getCachedProfile();
    if(cached){ renderProfileCard(cached); return; }
    fetch('https://api.github.com/users/'+GH_USER, {
      headers: { 'Accept': 'application/vnd.github.v3+json' }
    })
    .then(function(r){ if(!r.ok) throw new Error('gh '+r.status); return r.json(); })
    .then(function(data){ setCachedProfile(data); renderProfileCard(data); })
    .catch(function(){
      // graceful fallback — render with what we know so the card still appears
      renderProfileCard({
        name:'yuki', bio:'just your average gamer + otaku',
        location:'Patna, India', public_repos:3, followers:5, following:11,
        avatar_url:'https://github.com/'+GH_USER+'.png'
      });
    });
  }

  ready(function(){
    // Run a few times — the credit card itself is injected by other scripts
    // a bit after DOMContentLoaded, so we wait for it.
    var tries = 0;
    var iv = setInterval(function(){
      tries++;
      var done = cleanCreditLabels();
      if(done && !document.getElementById('gh-profile-card')) fetchProfile();
      if(tries > 40 || (done && document.getElementById('gh-profile-card'))) clearInterval(iv);
    }, 250);
  });
})();

/* ===== USER PATCH v2: reposition GitHub card + add bio card ===== */
(function(){
  function ready(fn){ document.readyState==='loading'
    ? document.addEventListener('DOMContentLoaded', fn) : fn(); }

  function ensureExtraWrap(){
    var about = document.getElementById('about');
    if(!about) return null;
    var wrap = document.getElementById('about-extra-wrap');
    if(wrap) return wrap;
    wrap = document.createElement('div');
    wrap.id = 'about-extra-wrap';
    wrap.className = 'about-extra-wrap';
    // Place RIGHT after the #about section, BEFORE the gradient-line +
    // skills section — which means it sits above the random-quote/time-link
    // panels (those live inside Skills/Now-Playing area below).
    about.insertAdjacentElement('afterend', wrap);
    return wrap;
  }

  function buildBioCard(){
    if(document.getElementById('bio-card')) return;
    var wrap = ensureExtraWrap();
    if(!wrap) return;
    var section = document.createElement('section');
    section.id = 'bio-card';
    section.setAttribute('aria-label', "reze's bio");
    section.innerHTML = ''
      + '<div class="bio-title">reze\u2019s bio</div>'
      + '<div class="bio-tag">~ 18 \u00b7 M \u00b7 \ud83c\uddee\ud83c\uddf3 India</div>'
      + '<div class="bio-section">'
      +   '<div class="bio-h">Interests</div>'
      +   '<p class="bio-p">Anime, story games (highly despise competitive FPS \u2014 <em>bad and proud</em>), and music \u2014 anything my ears like, but mostly J\u2011pop, EDM, and a healthy dose of \u201cwhite girl music\u201d.</p>'
      + '</div>'
      + '<div class="bio-section">'
      +   '<div class="bio-h">Devices Owned</div>'
      +   '<div class="bio-devices">'
      +     '<div class="bio-device"><span class="lbl">Primary</span><span class="val">Realme GT Neo 3 \u00b7 8/128<span class="sub">RMX3561 \u00b7 lisaa</span></span></div>'
      +     '<div class="bio-device"><span class="lbl">Secondary</span><span class="val">Samsung Galaxy J7 Prime<span class="sub">G610-F</span></span></div>'
      +     '<div class="bio-device"><span class="lbl">Laptop</span><span class="val">Lenovo IdeaPad 320<span class="sub">4GB RAM \u00b7 1TB HDD \u00b7 i3\u20116006U \u00b7 Intel HD 520</span></span></div>'
      +   '</div>'
      + '</div>'
      + '<div class="bio-section">'
      +   '<div class="bio-h">Games I play daily / often</div>'
      +   '<ul class="bio-games">'
      +     '<li>Crystal of Atlan</li>'
      +     '<li>Aether Gazer</li>'
      +     '<li>Punishing: Gray Raven</li>'
      +     '<li>Racing Master SEA</li>'
      +     '<li>Delta Force Mobile Global</li>'
      +     '<li>MiSide</li>'
      +   '</ul>'
      + '</div>';
    // Insert bio at TOP of wrap so it sits above the GitHub card.
    wrap.insertBefore(section, wrap.firstChild);
  }

  function moveGithubCard(){
    var gh = document.getElementById('gh-profile-card');
    if(!gh) return false;
    var wrap = ensureExtraWrap();
    if(!wrap) return false;
    if(gh.parentNode !== wrap){
      wrap.appendChild(gh); // ensures it ends up after the bio card
    }
    return true;
  }

  ready(function(){
    // Build the bio card immediately (doesn't depend on github fetch)
    buildBioCard();
    // The github card is injected asynchronously by the v1 patch; poll until
    // it shows up, then relocate it.
    var n = 0;
    var iv = setInterval(function(){
      n++;
      moveGithubCard();
      // Re-assert order in case anything else re-parents things
      var wrap = document.getElementById('about-extra-wrap');
      var bio  = document.getElementById('bio-card');
      var gh   = document.getElementById('gh-profile-card');
      if(wrap && bio && gh && wrap.firstChild !== bio){
        wrap.insertBefore(bio, wrap.firstChild);
      }
      if(n > 60) clearInterval(iv);
    }, 250);
  });
})();

/* ===== USER PATCH v3: route ALL game-icon clicks to true full-page playground ===== */
(function(){
  function ready(fn){ document.readyState==='loading'
    ? document.addEventListener('DOMContentLoaded', fn) : fn(); }

  function enterGameMode(){
    document.body.classList.add('gx-game-mode');
    try{ history.replaceState(null,'','#games'); }catch(e){}
    window.scrollTo({ top: 0, behavior: 'auto' });
  }
  function exitGameMode(){
    document.body.classList.remove('gx-game-mode');
    try{ history.replaceState(null,'','#hero'); }catch(e){}
  }
  window.gxShowGames = enterGameMode;   // override v1
  window.gxShowHome  = exitGameMode;    // override v1

  // Hard-route every "go to games/playground" entry point.
  function isGameTrigger(el){
    if(!el) return false;
    // Topbar / floating chips / any anchor whose title/text/href mentions games
    var title = (el.getAttribute && (el.getAttribute('title')||'')) || '';
    var ds    = (el.dataset && el.dataset.section) || '';
    var href  = (el.getAttribute && (el.getAttribute('href')||'')) || '';
    var txt   = (el.textContent || '').trim();
    if(el.classList && (el.classList.contains('gx-game-home') || el.classList.contains('gx-game-icon'))) return true;
    if(/^(games|playground)$/i.test(ds)) return true;
    if(/#(games|gx-games|gx-game-page|playground)/i.test(href)) return true;
    if(/^(games|playground|🎮.*|.*🎮)$/i.test(txt)) return true;
    if(/games?|playground/i.test(title)) return true;
    return false;
  }

  function onClick(e){
    var a = e.target.closest && e.target.closest('a, button, [role="button"]');
    if(!a) return;
    if(isGameTrigger(a)){
      e.preventDefault();
      e.stopPropagation();
      enterGameMode();
    }
  }

  // Use capture so we beat the page's existing scrollToSection() handler.
  document.addEventListener('click', onClick, true);

  // Browser back gesture / hashchange should also exit game mode if the URL
  // no longer points at #games.
  window.addEventListener('hashchange', function(){
    var h = (location.hash||'').toLowerCase();
    if(h === '#games' || h === '#gx-games' || h === '#gx-game-page' || h === '#playground'){
      enterGameMode();
    } else if(document.body.classList.contains('gx-game-mode')){
      exitGameMode();
    }
  });

  // If the page loaded directly with #games in the URL, activate game mode.
  ready(function(){
    var h = (location.hash||'').toLowerCase();
    if(h === '#games' || h === '#gx-games' || h === '#gx-game-page' || h === '#playground'){
      // Wait one frame so the playground section has time to be injected.
      setTimeout(enterGameMode, 50);
    }
  });
})();

/* ===== USER PATCH v4: keep modal in sync with game-mode transitions ===== */
(function(){
  function closeGameModal(){
    var m = document.getElementById('final-game-modal');
    if(!m) return;
    m.classList.remove('open');
    var game = m.querySelector('.fgm-game');
    if(game) game.innerHTML = '';   // stop any running RAF / timers' visible state
  }

  // Re-wrap the v3 helpers so they always close the modal first.
  var prevEnter = window.gxShowGames;
  var prevExit  = window.gxShowHome;

  window.gxShowGames = function(){
    closeGameModal();
    if(typeof prevEnter === 'function') return prevEnter();
    document.body.classList.add('gx-game-mode');
  };
  window.gxShowHome = function(){
    closeGameModal();
    if(typeof prevExit === 'function') return prevExit();
    document.body.classList.remove('gx-game-mode');
  };

  // Also catch clicks on the "← Return" button directly, in case the inline
  // onclick handler fires before our wrapper is in place.
  document.addEventListener('click', function(e){
    var b = e.target.closest && e.target.closest('.gx-game-return');
    if(b) closeGameModal();
  }, true);

  // And on hashchange away from #games, ensure the modal is closed.
  window.addEventListener('hashchange', function(){
    var h = (location.hash||'').toLowerCase();
    if(h !== '#games' && h !== '#gx-games' && h !== '#gx-game-page' && h !== '#playground'){
      closeGameModal();
    }
  });
})();

/* ===== USER PATCH v5: ensure modal is attached to <body> and visible ===== */
(function(){
  function findModal(){ return document.getElementById('final-game-modal'); }

  // If the modal exists but isn't a direct child of <body>, move it there so
  // it isn't subject to any wrapper's display:none rules.
  function reparentModal(){
    var m = findModal();
    if(m && m.parentNode !== document.body){
      document.body.appendChild(m);
    }
  }

  // Watch for the modal getting injected (it's created lazily on first click).
  var mo = new MutationObserver(function(){
    var m = findModal();
    if(m){
      reparentModal();
      // If a game just started, force-show it with inline styles that beat
      // any !important rule from earlier patches.
      if(m.classList.contains('open')){
        m.style.cssText += 'display:flex !important; visibility:visible !important; opacity:1 !important; z-index:2147483000 !important;';
      } else {
        // make sure the inline display override clears when closed
        m.style.removeProperty('display');
      }
    }
  });
  if(document.body) mo.observe(document.body, {childList:true, subtree:true, attributes:true, attributeFilter:['class']});
  else document.addEventListener('DOMContentLoaded', function(){
    mo.observe(document.body, {childList:true, subtree:true, attributes:true, attributeFilter:['class']});
  });
})();




