/* ===== USER REQUEST FIX v8 2026-07-01: one game opener + interaction-forced music ===== */
(function(){
  var autoStarted=false, attempts=0;
  function playerState(){try{return (typeof ytPlayerObj!=='undefined'&&ytPlayerObj&&ytPlayerObj.getPlayerState)?ytPlayerObj.getPlayerState():null;}catch(e){return null;}}
  function markPlaying(){
    // Do not show the topbar pulse until the player actually reports PLAYING.
    var playIcon=document.getElementById('sp-icon-play'), pauseIcon=document.getElementById('sp-icon-pause');
    if(playIcon) playIcon.style.display='none';
    if(pauseIcon) pauseIcon.style.display='block';
  }
  function ensurePoolMusic(){
    if(autoStarted && playerState()===1) return;
    autoStarted=true; attempts++;
    markPlaying();
    try{
      if(typeof ytPlayerObj!=='undefined' && ytPlayerObj && typeof ytPlayerObj.playVideo==='function'){
        try{ytPlayerObj.unMute&&ytPlayerObj.unMute();}catch(e){}
        try{ytPlayerObj.setVolume&&ytPlayerObj.setVolume(70);}catch(e){}
        ytPlayerObj.playVideo();
        if(typeof startProgressAnim==='function') startProgressAnim();
      }else if(attempts===1 && typeof togglePlay==='function'){
        togglePlay();
      }
    }catch(e){}
    // No hidden iframe fallback here: it creates duplicate/overlapping audio.
    if(attempts<8 && playerState()!==1) setTimeout(ensurePoolMusic,500);
  }
  window.ensurePoolMusic=ensurePoolMusic;
  ['pointerdown','touchstart','click','keydown'].forEach(function(ev){
    window.addEventListener(ev,function(e){
      if(e.target&&e.target.closest&&e.target.closest('.tb-music-icon,#tb-music-disc,#slide-music-player')) return;
      ensurePoolMusic();
    },{capture:true,passive:true});
  });
})();

