/* ===== USER REQUEST FIX v13 2026-07-01: single authoritative music player, no overlap ===== */
(function(){
  const SRC='https://raw.githubusercontent.com/4nx3b/4nx3b/main/09.%20in%20the%20pool.mp3';
  let userPaused=false;
  let firstInteractionTried=false;

  function audio(){
    let a=document.getElementById('arena-single-music-audio');
    if(!a){
      a=document.createElement('audio');
      a.id='arena-single-music-audio';
      a.preload='auto';
      a.loop=true;
      a.playsInline=true;
      a.crossOrigin='anonymous';
      a.volume=.85;
      a.src=SRC;
      a.style.display='none';
      document.body.appendChild(a);
      ['play','pause','ended','timeupdate','loadedmetadata','volumechange'].forEach(ev=>a.addEventListener(ev,sync));
    }
    return a;
  }
  function killOtherPlayers(){
    try{ if(typeof ytPlayerObj!=='undefined'&&ytPlayerObj&&ytPlayerObj.pauseVideo) ytPlayerObj.pauseVideo(); }catch(e){}
    try{ if(typeof htmlAudioObj!=='undefined'&&htmlAudioObj&&htmlAudioObj.pause) htmlAudioObj.pause(); }catch(e){}
    try{
      document.querySelectorAll('audio').forEach(function(x){ if(x.id!=='arena-single-music-audio'){ try{x.pause();}catch(e){} } });
    }catch(e){}
    try{
      const wrap=document.getElementById('yt-music-iframe');
      if(wrap) wrap.innerHTML='';
    }catch(e){}
  }
  function sync(){
    const a=audio();
    const playing=!a.paused && !a.ended && a.currentTime>=0;
    document.body.classList.toggle('music-playing',playing);
    const disc=document.getElementById('tb-music-disc'), vinyl=document.getElementById('sp-vinyl');
    const eq=document.getElementById('tb-eq-bars'), dots=document.getElementById('tb-three-dots');
    const playIcon=document.getElementById('sp-icon-play'), pauseIcon=document.getElementById('sp-icon-pause');
    disc&&disc.classList.toggle('spinning',playing);
    vinyl&&vinyl.classList.toggle('spinning',playing);
    if(eq) eq.style.display=playing?'flex':'none';
    if(dots) dots.style.display=playing?'none':'flex';
    if(playIcon) playIcon.style.display=playing?'none':'block';
    if(pauseIcon) pauseIcon.style.display=playing?'block':'none';
    const fill=document.getElementById('sp-progress-fill');
    if(fill&&a.duration) fill.style.width=((a.currentTime/a.duration)*100)+'%';
    const curr=document.getElementById('sp-curr-time'), dur=document.getElementById('sp-duration');
    const fmt=s=>!isFinite(s)?'0:00':Math.floor(s/60)+':'+String(Math.floor(s%60)).padStart(2,'0');
    if(curr) curr.textContent=fmt(a.currentTime||0);
    if(dur) dur.textContent=fmt(a.duration||0);
    const title=document.getElementById('topbar-track-title'), artist=document.getElementById('topbar-track-artist');
    const st=document.getElementById('sp-title'), sa=document.getElementById('sp-artist');
    if(title) title.textContent='in the pool';
    if(artist) artist.textContent='kensuke ushio';
    if(st) st.textContent='in the pool';
    if(sa) sa.textContent='kensuke ushio • audio';
  }
  async function play(){
    userPaused=false;
    killOtherPlayers();
    const a=audio();
    a.muted=false;
    a.volume=Math.max(a.volume||0,.85);
    try{ await a.play(); }catch(e){}
    sync();
  }
  function pause(){
    userPaused=true;
    const a=audio();
    try{a.pause();}catch(e){}
    killOtherPlayers();
    sync();
  }
  async function toggle(){
    const a=audio();
    if(a.paused) await play(); else pause();
  }
  function openMini(){
    const p=document.getElementById('slide-music-player');
    if(!p)return;
    p.classList.add('active');
    p.style.display='flex'; p.style.opacity='1'; p.style.visibility='visible'; p.style.pointerEvents='auto';
  }
  function isThumb(t){return !!(t&&t.closest&&t.closest('.tb-music-icon,#tb-music-disc'));}
  function isMiniPlay(t){return !!(t&&t.closest&&t.closest('.sp-play-btn,#sp-play-btn'));}
  function isMiniOpen(t){return !!(t&&t.closest&&t.closest('.tb-music-text,.tb-music-dots'));}
  function isMusicUi(t){return !!(t&&t.closest&&t.closest('.topbar-music-widget,#slide-music-player'));}

  window.togglePlay=toggle;
  window.ensurePoolMusic=play;
  window.__arenaSyncMusicPulse=sync;

  // Highest-priority controls: prevent older handlers from starting YouTube/duplicate audio.
  window.addEventListener('click',function(e){
    if(isThumb(e.target)||isMiniPlay(e.target)){
      e.preventDefault(); e.stopPropagation(); e.stopImmediatePropagation();
      toggle();
      return;
    }
    if(isMiniOpen(e.target)){
      e.preventDefault(); e.stopPropagation(); e.stopImmediatePropagation();
      openMini();
      return;
    }
  },true);

  // Autoplay after the first real interaction anywhere outside the music UI.
  function interaction(e){
    if(isMusicUi(e.target)) return;
    if(userPaused) return;
    if(!firstInteractionTried){ firstInteractionTried=true; play(); }
    else if(audio().paused){ play(); }
  }
  ['pointerdown','touchstart','click','keydown'].forEach(ev=>window.addEventListener(ev,interaction,{capture:true,passive:true}));

  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',function(){audio();sync();}); else {audio();sync();}
  setInterval(sync,800);
})();

