/* ===== USER REQUEST FIX v15 2026-07-01: remove music pulse + changelog sort filter ===== */
(function(){
  function removeMusicPulse(){
    var eq=document.getElementById('tb-eq-bars');
    var dots=document.getElementById('tb-three-dots');
    if(eq){
      eq.classList.remove('playing');
      eq.style.display='none';
      eq.style.visibility='hidden';
      eq.style.opacity='0';
      eq.querySelectorAll('.bar').forEach(function(b){b.style.animation='none';b.style.transform='none';});
    }
    if(dots){
      dots.classList.remove('playing');
      dots.style.display='flex';
      dots.style.visibility='visible';
      dots.style.opacity='1';
    }
    document.getElementById('tb-music-disc')?.classList.remove('spinning');
    document.getElementById('sp-vinyl')?.classList.remove('spinning');
  }

  function parseEntryTime(entry){
    var d=entry.querySelector('.gx-changelog-date');
    if(!d) return 0;
    var date=(d.childNodes[0]&&d.childNodes[0].textContent||d.textContent||'').trim();
    var time=(d.querySelector('span')?.textContent||'00:00').trim();
    var stamp=Date.parse(date+' '+time.replace(/IST/i,'+05:30'));
    if(!Number.isFinite(stamp)) stamp=Date.parse(date)||0;
    return stamp||0;
  }
  function sortChangelog(order){
    var list=document.querySelector('#gx-changelog-modal .gx-changelog-list');
    if(!list) return;
    var entries=[].slice.call(list.querySelectorAll('.gx-changelog-entry'));
    entries.sort(function(a,b){
      return order==='oldest' ? parseEntryTime(a)-parseEntryTime(b) : parseEntryTime(b)-parseEntryTime(a);
    });
    entries.forEach(function(entry){list.appendChild(entry);});
    list.dataset.order=order;
    document.querySelectorAll('.gx-changelog-filter').forEach(function(btn){btn.classList.toggle('active',btn.dataset.order===order);});
  }
  function ensureChangelogFilters(){
    var card=document.querySelector('#gx-changelog-modal .gx-changelog-card');
    var title=document.getElementById('gx-changelog-title');
    var list=document.querySelector('#gx-changelog-modal .gx-changelog-list');
    if(!card||!title||!list) return;
    if(!card.querySelector('.gx-changelog-controls')){
      var controls=document.createElement('div');
      controls.className='gx-changelog-controls';
      controls.innerHTML='<button type="button" class="gx-changelog-filter active" data-order="recent">Recent</button><button type="button" class="gx-changelog-filter" data-order="oldest">Oldest</button>';
      title.insertAdjacentElement('afterend',controls);
      controls.addEventListener('click',function(e){
        var b=e.target.closest('.gx-changelog-filter');
        if(!b) return;
        sortChangelog(b.dataset.order||'recent');
      });
    }
    sortChangelog(list.dataset.order||'recent');
  }
  function addChangelog(){
    var list=document.querySelector('#gx-changelog-modal .gx-changelog-list');
    if(!list||list.dataset.fixV15==='1') return;
    list.dataset.fixV15='1';
    var a=document.createElement('article');
    a.className='gx-changelog-entry fx-scoped-reveal fx-scoped-visible';
    a.innerHTML='<div class="gx-changelog-date">2026-07-01 <span>18:30 IST</span></div><ul><li>Removed the buggy topbar pulse/equalizer animation completely.</li><li>Kept the music player state clean with static dots instead of animated pulse lines.</li><li>Added Recent and Oldest filters to the Changelogs popup.</li></ul>';
    list.prepend(a);
  }
  function run(){removeMusicPulse();ensureChangelogFilters();addChangelog();ensureChangelogFilters();}
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',run); else run();
  setInterval(run,1000);
})();

/* ===== USER REQUEST FIX v_pager 2026-07-01: changelog pagination pills ===== */
(function(){
  var MIN_PER_PAGE = 3; // minimum number of changelog entries shown on every page

  function getList(){ return document.querySelector('#gx-changelog-modal .gx-changelog-list'); }
  function getCard(){ return document.querySelector('#gx-changelog-modal .gx-changelog-card'); }

  function paginateChangelog(){
    var list=getList(), card=getCard();
    if(!list || !card) return;
    var entries=[].slice.call(list.children).filter(function(el){return el.classList.contains('gx-changelog-entry');});
    if(!entries.length) return;

    var totalPages=Math.max(1, Math.ceil(entries.length / MIN_PER_PAGE));
    var page=Math.min(Math.max(1, Number(list.dataset.clPage) || 1), totalPages);
    list.dataset.clPage=String(page);

    entries.forEach(function(entry, i){
      var entryPage=Math.floor(i / MIN_PER_PAGE) + 1;
      entry.style.display = (entryPage === page) ? '' : 'none';
    });

    renderPagePills(card, list, totalPages, page);
  }

  function goToPage(list, n){
    list.dataset.clPage=String(n);
    paginateChangelog();
    var scrollTarget=list.closest('.gx-changelog-card') || list;
    scrollTarget.scrollTop=0;
    list.scrollTop=0;
  }

  function renderPagePills(card, list, totalPages, page){
    var wrap=card.querySelector('.gx-changelog-page-pills');
    if(totalPages<=1){ if(wrap) wrap.remove(); return; }

    var controls=card.querySelector('.gx-changelog-controls');

    // Keep the page pills docked inside the filter controls row (to the right of Recent/Oldest),
    // even if the controls row didn't exist yet when the pills were first created.
    if(wrap && controls && wrap.parentElement!==controls){ controls.appendChild(wrap); }

    var sig=totalPages+'|'+page;
    if(wrap && wrap.dataset.sig===sig) return;

    if(!wrap){
      wrap=document.createElement('div');
      wrap.className='gx-changelog-page-pills';
      if(controls) controls.appendChild(wrap); else list.insertAdjacentElement('afterend', wrap);
    }
    wrap.dataset.sig=sig;
    wrap.innerHTML=Array.from({length:totalPages}, function(_, i){
      var n=i+1;
      return '<button type="button" class="gx-changelog-page-pill'+(n===page?' active':'')+'" data-page="'+n+'">'+n+'</button>';
    }).join('');
    wrap.querySelectorAll('.gx-changelog-page-pill').forEach(function(btn){
      btn.addEventListener('click', function(){ goToPage(list, Number(btn.dataset.page)||1); });
    });
  }

  function watchFilters(){
    if(document.body.dataset.clFilterWatch==='1') return;
    document.body.dataset.clFilterWatch='1';
    document.addEventListener('click', function(e){
      var b=e.target.closest('.gx-changelog-filter');
      if(!b) return;
      var list=getList();
      if(list){ list.dataset.clPage='1'; setTimeout(paginateChangelog, 0); }
    }, true);
  }

  function run(){ watchFilters(); paginateChangelog(); }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded', run); else run();
  setInterval(run, 700);
})();

