    window.__arenaModalOpenGuardUntil=Date.now()+420;
    window.__arenaSyncPopupLock?.();
    validate();
    try{ window.__amaForceCloseKeyboard && window.__amaForceCloseKeyboard(); }catch(e){}
    [0,60,120,200,350,500].forEach(function(t){ setTimeout(function(){ try{ window.__amaAdjustModalToViewport && window.__amaAdjustModalToViewport(); }catch(e){} }, t); });
