/* ===== USER REQUEST FIX v17 2026-07-01: stable mini-player play/pause icon ===== */
(function(){
  function authoritativeAudio(){
    return document.getElementById('arena-single-music-audio') || document.getElementById('arena-music-audio') || null;
  }
  function audioActuallyPlaying(){
    var a=authoritativeAudio();
    return !!(a && !a.paused && !a.ended && a.readyState > 1);
  }
  function stabilizePlayButton(){
    var playing=audioActuallyPlaying();
    var btn=document.getElementById('sp-play-btn') || document.querySelector('#slide-music-player .sp-play-btn');
    if(btn){
      btn.classList.toggle('ap-playing',playing);
      btn.setAttribute('aria-label',playing?'Pause music':'Play music');
      btn.setAttribute('title',playing?'Pause':'Play');
    }
    // Stop older handlers from visually fighting over the two SVGs.
    ['sp-icon-play','sp-icon-pause'].forEach(function(id){
      var el=document.getElementById(id);
      if(el){
        el.style.setProperty('display','none','important');
        el.style.setProperty('visibility','hidden','important');
        el.style.setProperty('opacity','0','important');
      }
    });
    // Keep body state aligned to the real audio to stop other UI flicker.
    document.body.classList.toggle('music-playing',playing);
  }
  function bind(){
    var a=authoritativeAudio();
    if(a && a.dataset.stableIconBound!=='1'){
      a.dataset.stableIconBound='1';
      ['play','pause','ended','waiting','playing','timeupdate','volumechange'].forEach(function(ev){a.addEventListener(ev,stabilizePlayButton);});
    }
    stabilizePlayButton();
  }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',bind); else bind();
  setInterval(bind,150);
})();

