/* ===== USER REQUEST FIX v18 2026-07-01: structured AMA compose popup ===== */
(function(){
  function $(id){return document.getElementById(id);}
  function ensureAmaComposeStructure(){
    var modal=$('ama-name-modal'); if(!modal) return;
    var card=modal.querySelector('.ama-modal-card'); if(!card) return;
    var title=$('ama-name-title');
    var name=$('ama-name-input');
    var send=$('ama-final-send');
    if(title) title.textContent='Question';
    var p=card.querySelector('p'); if(p) p.textContent='';
    var kicker=card.querySelector('.ama-modal-kicker'); if(kicker) kicker.textContent='';

    var qLabel=$('ama-compose-question-label');
    if(!qLabel){
      qLabel=document.createElement('div');
      qLabel.id='ama-compose-question-label';
      qLabel.className='ama-compose-label';
      qLabel.textContent='Question';
      if(title) title.insertAdjacentElement('afterend',qLabel); else card.insertBefore(qLabel,card.firstChild);
    }
    var q=$('ama-popup-question-input');
    if(!q){
      q=document.createElement('textarea');
      q.id='ama-popup-question-input';
      q.className='ama-popup-question';
      q.maxLength=280;
      q.placeholder='Type your question...';
      q.autocomplete='off';
      qLabel.insertAdjacentElement('afterend',q);
    }else if(q.previousElementSibling!==qLabel){
      qLabel.insertAdjacentElement('afterend',q);
    }

    var nLabel=$('ama-compose-name-label');
    if(!nLabel){
      nLabel=document.createElement('div');
      nLabel.id='ama-compose-name-label';
      nLabel.className='ama-compose-label';
      nLabel.textContent='Your Name';
      if(name) name.insertAdjacentElement('beforebegin',nLabel); else q.insertAdjacentElement('afterend',nLabel);
    }
    if(name){
      name.placeholder='Your name';
      name.type='text';
      name.autocomplete='name';
      if(name.previousElementSibling!==nLabel) nLabel.insertAdjacentElement('afterend',name);
    }
    if(send && name && send.previousElementSibling!==name) name.insertAdjacentElement('afterend',send);

    function syncAndValidate(){
      var inline=$('ama-question-input');
      if(inline) inline.value=q.value;
      var ok=!!(q.value.trim() && (($('ama-name-input')?.value||'').trim()));
      if(send){
        send.disabled=!ok;
        send.setAttribute('aria-disabled',ok?'false':'true');
      }
    }
    if(q.dataset.boundV18!=='1'){
      q.dataset.boundV18='1';
      ['input','change','keyup','compositionend'].forEach(function(ev){q.addEventListener(ev,syncAndValidate,true);});
    }
    if(name && name.dataset.boundV18!=='1'){
      name.dataset.boundV18='1';
      ['input','change','keyup','compositionend'].forEach(function(ev){name.addEventListener(ev,syncAndValidate,true);});
    }
    syncAndValidate();
  }
  function openCompose(e){
    if(e){e.preventDefault();e.stopPropagation();e.stopImmediatePropagation();}
    ensureAmaComposeStructure();
    var modal=$('ama-name-modal'); if(!modal) return;
    var q=$('ama-popup-question-input'), inline=$('ama-question-input');
    if(q && inline && inline.value && !q.value) q.value=inline.value;
    modal.classList.add('open');
    modal.setAttribute('aria-hidden','false');
    document.body.classList.add('ama-modal-open');
    window.__arenaModalOpenGuardUntil=Date.now()+420;
    window.__arenaSyncPopupLock?.();
    ensureAmaComposeStructure();
    try{ window.__amaForceCloseKeyboard && window.__amaForceCloseKeyboard(); }catch(err){}
    [0,60,120,200,350,500].forEach(function(t){ setTimeout(function(){ try{ window.__amaAdjustModalToViewport && window.__amaAdjustModalToViewport(); }catch(err){} }, t); });
  }
  function trigger(t){return !!(t&&t.closest&&t.closest('#ama-question-input,#ama-question-next,#ama-question-form'));}
  ['pointerdown','click'].forEach(function(ev){
    document.addEventListener(ev,function(e){
      if(e.target&&e.target.closest&&e.target.closest('#ama-name-modal')) return;
      if(trigger(e.target)) openCompose(e);
    },true);
  });
  document.addEventListener('submit',function(e){if(e.target&&e.target.id==='ama-question-form') openCompose(e);},true);
  document.addEventListener('click',function(e){
    var send=e.target&&e.target.closest&&e.target.closest('#ama-final-send');
    if(!send) return;
    ensureAmaComposeStructure();
    var q=$('ama-popup-question-input'), inline=$('ama-question-input');
    if(q&&inline) inline.value=q.value;
    if(send.disabled){e.preventDefault();e.stopPropagation();e.stopImmediatePropagation();}
  },true);
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',ensureAmaComposeStructure); else ensureAmaComposeStructure();
  setInterval(ensureAmaComposeStructure,1000);
})();

