/* ===== USER REQUEST FIX v19 2026-07-01: stop changelog flicker + keep AMA name visible ===== */
(function(){
  // Legacy code was re-appending every changelog entry every second, which caused flicker.
  // Block automatic re-appends, but allow explicit Recent/Oldest sorting through our buttons.
  if(!window.__changelogAppendPatchV19){
    window.__changelogAppendPatchV19=true;
    var nativeAppend=Element.prototype.appendChild;
    Element.prototype.appendChild=function(child){
      try{
        if(this.classList&&this.classList.contains('gx-changelog-list')&&child&&child.parentNode===this&&!window.__allowChangelogSortV19){
          return child;
        }
      }catch(e){}
      return nativeAppend.call(this,child);
    };
  }
  function parseEntryTime(entry){
    var d=entry.querySelector('.gx-changelog-date');
    if(!d)return 0;
    var date=(d.childNodes[0]&&d.childNodes[0].textContent||d.textContent||'').trim();
    var time=(d.querySelector('span')?.textContent||'00:00').trim();
    var stamp=Date.parse(date+' '+time.replace(/IST/i,'+05:30'));
    return Number.isFinite(stamp)?stamp:(Date.parse(date)||0);
  }
  function sortChangelog(order){
    var list=document.querySelector('#gx-changelog-modal .gx-changelog-list'); if(!list)return;
    var entries=[].slice.call(list.querySelectorAll('.gx-changelog-entry'));
    entries.sort(function(a,b){return order==='oldest'?parseEntryTime(a)-parseEntryTime(b):parseEntryTime(b)-parseEntryTime(a);});
    window.__allowChangelogSortV19=true;
    entries.forEach(function(e){list.appendChild(e);});
    window.__allowChangelogSortV19=false;
    list.dataset.order=order;
    document.querySelectorAll('.gx-changelog-filter').forEach(function(b){b.classList.toggle('active',b.dataset.order===order);});
  }
  function wireFilters(){
    var card=document.querySelector('#gx-changelog-modal .gx-changelog-card');
    var title=document.getElementById('gx-changelog-title');
    if(!card||!title)return;
    var controls=card.querySelector('.gx-changelog-controls');
    if(!controls){
      controls=document.createElement('div');
      controls.className='gx-changelog-controls';
      controls.innerHTML='<button type="button" class="gx-changelog-filter active" data-order="recent">Recent</button><button type="button" class="gx-changelog-filter" data-order="oldest">Oldest</button>';
      title.insertAdjacentElement('afterend',controls);
    }
    if(controls.dataset.v19!=='1'){
      controls.dataset.v19='1';
      controls.addEventListener('click',function(e){
        var b=e.target.closest('.gx-changelog-filter'); if(!b)return;
        e.preventDefault(); e.stopPropagation();
        sortChangelog(b.dataset.order||'recent');
      },true);
    }
  }
  function keepAmaVisible(){
    var modal=document.getElementById('ama-name-modal'); if(!modal||!modal.classList.contains('open'))return;
    var name=document.getElementById('ama-name-input');
    if(name){
      name.style.setProperty('display','block','important');
      name.style.setProperty('visibility','visible','important');
      name.style.setProperty('opacity','1','important');
    }
  }
  function addChangelog(){
    var list=document.querySelector('#gx-changelog-modal .gx-changelog-list');
    if(!list||list.dataset.fixV19==='1')return;
    list.dataset.fixV19='1';
    var a=document.createElement('article');
    a.className='gx-changelog-entry fx-scoped-reveal fx-scoped-visible';
    a.innerHTML='<div class="gx-changelog-date">2026-07-01 <span>19:15 IST</span></div><ul><li>Made the Ask Me Anything compose popup compact so the Your Name field stays visible on mobile keyboards.</li><li>Stopped Changelogs content from flickering by blocking legacy automatic reorders.</li><li>Kept the Recent and Oldest filters working without repeated background resorting.</li></ul>';
    window.__allowChangelogSortV19=true; list.prepend(a); window.__allowChangelogSortV19=false;
  }
  function run(){wireFilters();keepAmaVisible();addChangelog();}
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',run);else run();
  setInterval(run,1000);
})();

